insert into guides (id, content) values ('brakes-mk7', '{"title": "Brake pads & rotors", "category": "Brakes", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Front parts are shared with the Mk7 Golf R (340 mm) and the base Mk7 Golf / A3 (312 mm). Rear pads are not: the Golf R and EU cars with an electric parking brake use different rear pads.", "heroId": "mk7-brk-hero", "heroCap": "Front corner, exploded. Rear is the same idea with a handbrake mechanism behind the piston.", "variants": {"questions": [{"question": "Which brakes does your car have?", "hint": "Look through the wheel at the front caliper clip: a GTI logo means the bigger Performance brakes. 2019–2021 cars have them as standard.", "options": [{"id": "base", "label": "Base brakes", "when": "312 mm front, 272 mm solid rear. Most 2015–2018 S and SE cars."}, {"id": "pp", "label": "Performance brakes", "when": "340 mm front, 310 mm vented rear. Performance Package, Autobahn, Rabbit, all 2019–2021."}]}, {"question": "Which end are you doing?", "hint": "Fronts wear roughly twice as fast. Pads and rotors are always done in axle pairs.", "options": [{"id": "front", "label": "Front", "when": "Two corners, no special tools."}, {"id": "rear", "label": "Rear", "when": "Needs a piston wind-back tool."}, {"id": "both", "label": "Front and rear", "when": "A full afternoon."}]}, {"question": "Replacement or upgrade?", "options": [{"id": "oe", "label": "OE-equivalent parts", "when": "Same feel as new. Textar, Pagid, ATE, TRW pads; Zimmermann, ATE, Meyle rotors.", "oeOnly": true}, {"id": "perf", "label": "Performance pads and rotors", "when": "Stronger bite and more heat capacity on the factory calipers."}]}]}, "glance": {"why": "The single most-done job on any GTI, and the one where the rear pistons catch people out.", "timeFirst": "1.5–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$150–600", "risk": "Rear pistons screw back. Pushing them ruins the caliper.", "note": "Time is per axle. Cost is for one axle of pads and rotors with hardware; performance parts run higher."}, "lifespan": {"headline": ["First pads usually go at 20,000–40,000 miles"], "earliest": "Hard city or track use can need fronts sooner; highway cars can pass 60,000.", "detail": "Rotors are close to their limit when new (the 312 mm front goes from 25 mm to a 22 mm minimum), so most owners replace rotors with every pad change.", "factors": ["Stop-and-go driving", "Track days and autocross", "Aggressive pad compounds", "Sitting with your foot on hot brakes"], "inspect": ["Check pad thickness every 10,000 miles"], "confidence": {"level": "medium", "n": 1, "note": "Mileage ranges and rotor limits from FCP Euro''s Mk7 brake guide; real wear depends heavily on the driver."}}, "should": {"yesIf": ["The pad you can see through the wheel is down to about 5 mm", "There''s a raised lip at the outer edge of the rotor", "You feel a pulse through the pedal or steering wheel when braking", "Your dash shows the brake pad wear warning", {"text": "You want more bite and fade resistance for spirited driving or a track day", "only": ["perf"]}], "codes": [], "notes": ["Squeal alone isn''t a reason to replace. Clean and re-paste the pad contact points or re-bed the pads first.", "2015 cars often have no pad wear sensor, so there''s no dash warning. Check them by eye.", "This guide covers US-market cars, which use a handbrake lever. European cars with an electric parking-brake button need a scan tool to retract the rear calipers.", {"text": "Pads do most of the work in an upgrade. Fancy rotors mainly add bite in the wet, lose weight and look the part.", "only": ["perf"]}], "confidence": {"level": "high", "n": 3, "note": "FCP Euro''s Mk7 guide, ECS and Deutsche Auto Parts fitment listings."}}, "parts": [{"tier": "oem", "name": "Front rotors, 312 × 25 (pair)", "pn": "1K0 615 301 AA", "note": "Zimmermann, ATE, Meyle or Pagid.", "price": "$90–140", "only": ["base+front+oe", "base+both+oe"]}, {"tier": "oem", "name": "Front rotors, 340 × 30 (pair)", "note": "Same rotor as the Golf R. Zimmermann, ATE, Brembo.", "price": "$180–230", "only": ["pp+front+oe", "pp+both+oe"]}, {"tier": "oem", "name": "Front pad set", "note": "Textar, Pagid, ATE or TRW. Order for 312 or 340 mm rotors to match your car.", "price": "$50–90", "only": ["base+front+oe", "base+both+oe", "pp+front+oe", "pp+both+oe"]}, {"tier": "aftermarket", "name": "Performance front pad set", "note": "Pick a compound from the aftermarket list. Order for 312 or 340 mm rotors.", "price": "$100–275", "only": ["base+front+perf", "base+both+perf", "pp+front+perf", "pp+both+perf"]}, {"tier": "aftermarket", "name": "Performance front rotors (pair)", "note": "Slotted one-piece, or two-piece floating on 340 mm cars.", "price": "$190–1,060", "only": ["base+front+perf", "base+both+perf", "pp+front+perf", "pp+both+perf"]}, {"tier": "oe", "name": "Caliper guide bolts M8 × 22, front (4)", "note": "One-time use with threadlock already on them. OE pad boxes usually include them.", "price": "$5 each", "only": ["base+front+oe", "base+front+perf", "base+both+oe", "base+both+perf", "pp+front+oe", "pp+front+perf", "pp+both+oe", "pp+both+perf"]}, {"tier": "oe", "name": "Front carrier bolts M14 × 1.5 × 55 (4)", "note": "Optional. Reuse clean, undamaged bolts or replace them cheaply.", "price": "$10 each", "only": ["base+front+oe", "base+front+perf", "base+both+oe", "base+both+perf", "pp+front+oe", "pp+front+perf", "pp+both+oe", "pp+both+perf"]}, {"tier": "oe", "name": "Front pad wear sensor", "note": "Only if your car has one (left-front inner pad). Reuse it if the tip isn''t worn through.", "price": "$15", "only": ["base+front+oe", "base+front+perf", "base+both+oe", "base+both+perf", "pp+front+oe", "pp+front+perf", "pp+both+oe", "pp+both+perf"]}, {"tier": "oem", "name": "Rear rotors, 272 × 10 solid (pair)", "pn": "1K0 615 601 AA", "note": "Zimmermann, ATE, Meyle.", "price": "$60–100", "only": ["base+rear+oe", "base+both+oe"]}, {"tier": "oem", "name": "Rear rotors, 310 × 22 vented (pair)", "pn": "5Q0 615 601 E", "note": "Zimmermann, ATE, Brembo.", "price": "$140–200", "only": ["pp+rear+oe", "pp+both+oe"]}, {"tier": "oem", "name": "Rear pad set, 272 mm", "note": "Anti-rattle springs are built into the pads.", "price": "$40–70", "only": ["base+rear+oe", "base+both+oe"]}, {"tier": "oem", "name": "Rear pad set, 310 mm GTI", "note": "Comes with separate anti-rattle clips for the carrier. Golf R rear pads look similar but don''t fit.", "price": "$55–85", "only": ["pp+rear+oe", "pp+both+oe"]}, {"tier": "aftermarket", "name": "Performance rear pad set", "note": "Match the front compound family so the balance stays sensible.", "price": "$80–230", "only": ["base+rear+perf", "base+both+perf", "pp+rear+perf", "pp+both+perf"]}, {"tier": "aftermarket", "name": "Performance rear rotors (pair)", "note": "Slotted one-piece, or two-piece on 310 mm cars.", "price": "$150–600", "only": ["base+rear+perf", "base+both+perf", "pp+rear+perf", "pp+both+perf"]}, {"tier": "oe", "name": "Rear carrier bolts M12 × 1.5 × 65 (4)", "note": "Stretch bolts. Always new.", "price": "$7 each", "only": ["base+rear+oe", "base+rear+perf", "base+both+oe", "base+both+perf", "pp+rear+oe", "pp+rear+perf", "pp+both+oe", "pp+both+perf"]}, {"tier": "oe", "name": "Caliper guide bolts M8 × 22, rear (4)", "note": "One-time use, pre-coated.", "price": "$5 each", "only": ["base+rear+oe", "base+rear+perf", "base+both+oe", "base+both+perf", "pp+rear+oe", "pp+rear+perf", "pp+both+oe", "pp+both+perf"]}, {"tier": "oe", "name": "Rotor set screws, T30 (1 per rotor)", "note": "They rust into the hub; new ones are cheap.", "price": "$2–3 each"}, {"name": "Ceramic brake paste and silicone caliper grease", "note": "Paste for the pad contact points, grease for the guide pins.", "price": "$15"}, {"name": "Brake cleaner (2 cans)", "note": "New rotors ship with an oily anti-rust coat.", "price": "$10"}], "aftermarket": [{"name": "Ferodo DS2500 pads", "note": "Street and track in one pad: decent cold bite, holds up to repeated track sessions with proper fluid.", "price": "$200–275 per axle", "signal": "FCP Euro''s pick for their own Mk7 project car"}, {"name": "APR Advanced Street pads", "note": "OE-fit street pad with much better fade resistance and low rotor wear.", "price": "$100 / $155 front", "links": [{"store": "NGP (312 mm)", "url": "https://store.ngpracing.com/products/apr-front-brake-pads-vw-mk7-mk7-5-golf-gti-non-performance-pack-audi-8v-a3-8s-tt"}, {"store": "NGP (340 mm)", "url": "https://store.ngpracing.com/products/apr-front-brake-pads-vw-mk7-mk7-5-gti-with-performance-pack-golf-r-gli-audi-8v-a3-quattro-audi-8v-s3"}]}, {"name": "EBC Green, Red and Yellow Stuff", "note": "Green and Red are street pads; Yellow has much more bite for street and autocross but dislikes being overheated.", "price": "$90–140 per axle", "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/News/MK7_GTI_VW_EBC_Performance_Braking_27417/"}]}, {"name": "Hawk HPS or StopTech Sport pads", "note": "Low-dust, long-wearing street performance pads; a modest step up from OE.", "price": "$80–130 per axle"}, {"name": "StopTech slotted rotors + G-LOC R12 pads", "note": "Track kit for 312 mm cars. R12 is a race compound: noisy and dusty on the street.", "price": "about $690 front", "only": ["base+front+oe", "base+front+perf", "base+rear+oe", "base+rear+perf", "base+both+oe", "base+both+perf"], "links": [{"store": "Deutsche Auto Parts", "url": "https://www.shopdap.com/front-stoptech-g-loc-brake-kit-for-mk7-gti-track.html"}]}, {"name": "ECS two-piece rotors", "note": "Cross-drilled and slotted, sold for 312 front, 340 front and 310 rear. Saves 5–10 lb per pair.", "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/News/Volkswagen_MK7_GTI_ECS_2_Piece_Rotors_18967/"}]}, {"name": "034Motorsport two-piece floating front rotors", "note": "340 × 30 on the factory caliper. About 5 lb lighter per rotor than OE, replaceable rings.", "price": "$1,059 pair", "only": ["pp+front+oe", "pp+front+perf", "pp+rear+oe", "pp+rear+perf", "pp+both+oe", "pp+both+perf"], "links": [{"store": "NGP Racing", "url": "https://store.ngpracing.com/products/034motorsport-2-piece-floating-front-brake-rotor-upgrade-kit-for-audi-8v-8v-5-s3-and-vw-mk7-7-5-gti-r-034-301-1001"}]}, {"name": "Girodisc two-piece + G-Loc GS-1 front kit", "note": "Premium street kit for 340 mm cars; GS-1 is rotor-friendly and long-lived.", "price": "about $1,270 front", "only": ["pp+front+oe", "pp+front+perf", "pp+rear+oe", "pp+rear+perf", "pp+both+oe", "pp+both+perf"], "links": [{"store": "Deutsche Auto Parts", "url": "https://www.shopdap.com/front-girodisc-g-loc-brake-kit-for-sport-pp-gti-street-5g0-698-151-c-pp-gs1.html"}]}, {"name": "Clubsport S cross-drilled 340 rotors (OEM+)", "note": "Genuine VW part 5Q0 615 301 C from the European Clubsport. About 2 lb lighter per rotor than the standard 340.", "only": ["pp+front+oe", "pp+front+perf", "pp+rear+oe", "pp+rear+perf", "pp+both+oe", "pp+both+perf"], "links": [{"store": "NGP Racing", "url": "https://store.ngpracing.com/products/genuine-vw-mk7-gti-clubsport-s-cross-drilled-brake-rotors-340x30mm-fits-several-applications"}]}, {"name": "Performance brake swap (OEM+)", "note": "On base cars, fitting the full 340/310 Performance brakes is the classic factory-quality upgrade. Calipers, carriers, rotors and pads all change.", "only": ["base+front+oe", "base+front+perf", "base+rear+oe", "base+rear+perf", "base+both+oe", "base+both+perf"]}], "tools": [{"name": "Floor jack and two stands", "price": "$120"}, {"name": "17 mm wheel-bolt socket, ½\" breaker bar", "price": "$30"}, {"name": "½\" torque wrench reaching 200 Nm", "price": "$60"}, {"name": "Small ¼\" or ⅜\" torque wrench", "note": "For the 4 Nm set screws. Or just snug them.", "price": "$40"}, {"name": "21 mm socket", "note": "Front carrier bolts.", "price": "$8", "only": ["base+front+oe", "base+front+perf", "base+both+oe", "base+both+perf", "pp+front+oe", "pp+front+perf", "pp+both+oe", "pp+both+perf"]}, {"name": "14 mm triple-square (XZN) bit", "note": "Rear carrier bolts. Access is tight; a short bit helps.", "price": "$12", "only": ["base+rear+oe", "base+rear+perf", "base+both+oe", "base+both+perf", "pp+rear+oe", "pp+rear+perf", "pp+both+oe", "pp+both+perf"]}, {"name": "Angle gauge", "note": "For the rear carrier bolts'' extra 90°.", "price": "$12", "only": ["base+rear+oe", "base+rear+perf", "base+both+oe", "base+both+perf", "pp+rear+oe", "pp+rear+perf", "pp+both+oe", "pp+both+perf"]}, {"name": "13 mm socket or T45, plus a thin 15 mm open-end wrench", "note": "Guide bolts out while you hold the slide pin still.", "price": "$15"}, {"name": "T30 Torx bit", "note": "Rotor set screw.", "price": "$5"}, {"name": "Piston spreader or large pliers", "note": "Front pistons push straight back.", "price": "$15", "only": ["base+front+oe", "base+front+perf", "base+both+oe", "base+both+perf", "pp+front+oe", "pp+front+perf", "pp+both+oe", "pp+both+perf"]}, {"name": "Rear caliper wind-back tool", "note": "A cube or screw-type tool with an adapter whose pins fit the piston slots.", "price": "$25", "only": ["base+rear+oe", "base+rear+perf", "base+both+oe", "base+both+perf", "pp+rear+oe", "pp+rear+perf", "pp+both+oe", "pp+both+perf"]}, {"name": "Wire brush, rubber mallet, penetrating oil", "note": "Rusty rotors and hub faces.", "price": "$20"}, {"name": "Bungee or wire", "note": "So the caliper never hangs on its hose.", "price": "$3"}], "before": ["Loosen the wheel bolts a half turn with the car on the ground.", "Check the brake fluid level. If it''s at MAX, take a little out, because pushing pistons back raises it.", {"text": "Release the handbrake and chock the front wheels before lifting the rear.", "only": ["rear", "both"]}, "New rotors are coated in oil against rust. Clean both faces with brake cleaner before fitting.", "Work one side at a time so the other side is there to copy."], "chapters": [{"id": "front", "title": "Front brakes", "blurb": "Same on both sides. Do one corner start to finish, then the other."}, {"id": "rear", "title": "Rear brakes", "blurb": "The caliper carries the handbrake mechanism, so the piston screws back instead of pushing."}, {"id": "finish", "title": "Finish", "blurb": "Torque, pump, bed in."}], "steps": [{"chapter": "front", "only": ["front", "both"], "title": "Lift the car and take the wheel off", "blocks": [{"t": "text", "b": "Jack at the front pinch-weld, set a stand, and remove the wheel. Turn the steering away from the side you''re on for easier access to the back of the caliper."}, {"t": "ill", "id": "mk7-brk-id", "cap": "Not sure which brakes you have? Rotor size and the caliper clip tell you."}, {"t": "ill", "id": "mk7-brk-front", "cap": "Seen from inside the wheel well: carrier bolts behind, guide bolts on the caliper."}]}, {"chapter": "front", "only": ["front", "both"], "title": "Unplug the wear sensor and remove the caliper", "blocks": [{"t": "text", "b": "If a thin wire runs into the inner pad, unclip it from its holder and pull the sensor out of the pad."}, {"t": "text", "b": "Remove the caliper''s two guide bolts while holding the slide pin still with a thin 15 mm open-end wrench. Lift the caliper off the pads."}, {"t": "warn", "b": "Never let the caliper hang by its hose. Hang it from the spring with a bungee."}]}, {"chapter": "front", "only": ["front", "both"], "title": "Remove the pads, carrier and rotor", "timeSink": true, "blocks": [{"t": "text", "b": "Pull the pads out of the carrier. Undo the two 21 mm carrier bolts from behind the knuckle; they''re tight, so use the breaker bar."}, {"t": "text", "b": "Remove the T30 set screw and pull the rotor. If it''s rusted to the hub, soak the centre with penetrating oil and hit the hat area (not the friction face) with the mallet."}]}, {"chapter": "front", "only": ["front", "both"], "title": "Clean the hub and fit the new rotor", "blocks": [{"t": "text", "b": "Wire-brush the hub face until it''s bare metal. Any rust left between hub and rotor causes a pedal pulse that feels exactly like a warped rotor."}, {"t": "text", "b": "Fit the cleaned rotor and its set screw."}, {"t": "torque", "label": "rotor set screw", "nm": 4, "c": {"level": "varies", "n": 3, "note": "FCP Euro lists 4 Nm. Two owner transcriptions of the Mk7 manual list 8 Nm. It only locates the rotor; the wheel clamps it."}, "alt": [8]}]}, {"chapter": "front", "only": ["front", "both"], "title": "Refit the carrier", "caution": true, "blocks": [{"t": "text", "b": "Clean the carrier''s pad seats with the wire brush until the pad ears slide in without force. Put a thin film of ceramic paste where the pad ears sit."}, {"t": "text", "b": "Clean the carrier bolt threads and the knuckle holes, then fit the carrier."}, {"t": "torque", "label": "front carrier bolts", "nm": 200, "c": {"level": "high", "n": 3, "note": "200 Nm for the front carrier bolts appears in FCP Euro''s Mk7 torque list, the mygolfmk7 torque table and an owner''s factory-manual screenshot."}}]}, {"chapter": "front", "only": ["front", "both"], "title": "Push the piston back and fit the new pads", "blocks": [{"t": "text", "b": "Push the piston fully into the caliper with a spreader or large pliers using an old pad as a cushion. Watch the reservoir so it doesn''t overflow."}, {"t": "text", "b": "Pull each slide pin out of its boot, wipe it, add silicone grease and push it back. Fit the new pads into the carrier and the new anti-rattle clip if your pad set came with one."}, {"t": "note", "b": "Performance-brake cars: the clip with the GTI logo goes back on the outside of the caliper.", "only": ["pp+front+oe", "pp+front+perf", "pp+both+oe", "pp+both+perf"]}]}, {"chapter": "front", "only": ["front", "both"], "title": "Refit the caliper", "blocks": [{"t": "text", "b": "Lower the caliper over the pads, start both new guide bolts by hand, and hold the slide pin with the 15 mm wrench while you tighten."}, {"t": "torque", "label": "caliper guide bolts", "nm": 35, "c": {"level": "high", "n": 4, "note": "35 Nm with new pre-coated bolts: FCP Euro, mygolfmk7, a 2015 Golf manual transcription and a golfmk7.com member quoting the Golf R spec."}}, {"t": "text", "b": "Plug the wear sensor into the new inner pad and clip its wire back into the holder, clear of the rotor."}]}, {"chapter": "rear", "only": ["rear", "both"], "title": "Lift the rear and remove the caliper", "blocks": [{"t": "text", "b": "Handbrake off, fronts chocked. Lift, set stands and remove the wheel."}, {"t": "ill", "id": "mk7-brk-id", "cap": "Base rear discs are thin and solid; Performance rear discs are vented.", "only": ["rear"]}, {"t": "text", "b": "Remove the two caliper guide bolts while holding each slide pin with the 15 mm wrench. Lift the caliper off and hang it. The handbrake cable stays attached."}]}, {"chapter": "rear", "only": ["rear", "both"], "title": "Remove the pads, carrier and rotor", "timeSink": true, "blocks": [{"t": "text", "b": "Pull the pads. The two carrier bolts take a 14 mm triple-square bit and are awkward to reach behind the knuckle. Use a short bit and a breaker bar."}, {"t": "text", "b": "Remove the T30 set screw and the rotor, the same way as the front."}, {"t": "note", "b": "Base cars: the rear rotor is solid and thin, so don''t hit the friction face; tap the hat only.", "only": ["base+rear+oe", "base+rear+perf", "base+both+oe", "base+both+perf"]}]}, {"chapter": "rear", "only": ["rear", "both"], "title": "Clean the hub, fit the rotor and carrier", "caution": true, "blocks": [{"t": "text", "b": "Wire-brush the hub face, fit the clean rotor and its set screw."}, {"t": "text", "b": "Clean the carrier''s pad seats. Fit the carrier with new bolts: torque them, then turn each a further 90°."}, {"t": "torque", "label": "rear carrier bolts", "nm": 90, "c": {"level": "high", "n": 3, "note": "90 Nm plus a further 90°, new bolts: FCP Euro, a 2015 Golf manual transcription and golfmk7.com. Same family as the Mk5/Mk6 rear spec."}, "note": "+ 90°"}, {"t": "warn", "b": "These are stretch bolts. Reused ones can let go."}]}, {"chapter": "rear", "only": ["rear", "both"], "title": "Screw the piston back", "caution": true, "blocks": [{"t": "ill", "id": "mk7-brk-windback", "cap": "Clockwise while pressing in. No straight push."}, {"t": "text", "b": "Fit the wind-back tool so its pins sit in the two slots on the piston face. Turn clockwise while pressing in, until the piston is flush with the caliper body."}, {"t": "warn", "b": "Never push the rear piston straight in with a C-clamp or spreader. The handbrake screw behind it is what you''d be forcing."}]}, {"chapter": "rear", "only": ["rear", "both"], "title": "Fit the pads and refit the caliper", "blocks": [{"t": "note", "b": "Performance-brake cars: press the separate anti-rattle clips into the carrier first, then fit the pads.", "only": ["pp+rear+oe", "pp+rear+perf", "pp+both+oe", "pp+both+perf"]}, {"t": "note", "b": "Base cars: the springs are part of the pads. Clip each pad into the carrier.", "only": ["base+rear+oe", "base+rear+perf", "base+both+oe", "base+both+perf"]}, {"t": "text", "b": "Paste the pad ears lightly, grease the slide pins, lower the caliper and fit new guide bolts while holding the slide pins."}, {"t": "torque", "label": "caliper guide bolts", "nm": 35, "c": {"level": "high", "n": 4, "note": "35 Nm with new pre-coated bolts: FCP Euro, mygolfmk7, a 2015 Golf manual transcription and a golfmk7.com member quoting the Golf R spec."}}]}, {"chapter": "rear", "only": ["rear", "both"], "title": "Set the handbrake", "blocks": [{"t": "text", "b": "With the wheels back on, pull the handbrake lever up and release it five or six times. The mechanism behind the piston self-adjusts to the new pads. Check that the car holds on a slope before you trust it."}]}, {"chapter": "finish", "title": "Wheels on and torque", "blocks": [{"t": "text", "b": "Fit the wheels, lower the car and torque the bolts in a star pattern."}, {"t": "torque", "label": "wheel bolts", "nm": 120, "c": {"level": "high", "n": 3, "note": "120 Nm is the VW spec across MQB. Owner transcriptions round it to 119 Nm (88 lb-ft)."}}]}, {"chapter": "finish", "title": "Pump the pedal before you move", "caution": true, "blocks": [{"t": "text", "b": "Sit in the car and pump the brake pedal until it''s high and firm. The first few presses go nearly to the floor while the pistons come out to meet the pads."}, {"t": "text", "b": "Top the reservoir up to MAX if needed."}]}, {"chapter": "finish", "title": "Bed in the pads", "blocks": [{"t": "text", "b": "On a quiet road: six or eight moderate stops from 35 mph to about 5 mph, then three or four firmer stops from 50 mph. Don''t stop fully. Drive a few minutes without braking to cool them, and don''t sit with your foot on the pedal while they''re hot."}, {"t": "note", "b": "Performance pads often come with their own bed-in routine. Use theirs if it differs.", "only": ["perf"]}]}], "alsoReplace": [{"name": "Brake fluid", "why": "If it''s over two years old, flush it now. The wheels are already off and the bleed screws are in front of you."}, {"name": "Slide pin boots", "why": "Torn boots let water in and seize the pins, which wears one pad faster than the other."}, {"name": "Stainless brake lines", "why": "Natural partner to performance pads: a firmer pedal for the cost of a bleed you''re probably doing anyway.", "only": ["perf"]}], "check": {"tab": "Reading wear", "title": "Reading your pads and rotors", "illId": "mk7-brk-check", "illCap": "Measure friction material only. The inner pad tells the truth.", "rows": [{"see": "Outer pad around 5 mm, rotor smooth with no lip", "means": "The inner pad is likely thinner than what you can see.", "do": "Plan the job within a few thousand miles; pull a wheel to check the inner pad."}, {"see": "Pad 2 mm or less, or a lip you can catch a fingernail on", "means": "At or past the limit.", "do": "Replace pads and rotors as a set now."}, {"see": "Pedal pulse with plenty of pad left", "means": "Uneven pad deposits on the rotor, or rust between hub and rotor.", "do": "Try a re-bed first; if it stays, replace the rotors and clean the hub faces bare."}], "c": {"level": "high", "n": 1, "note": "Thickness limits and the rotor-limit figures from FCP Euro''s Mk7 guide."}}, "aftercare": ["Recheck wheel bolt torque after the first 50 miles.", "Expect a little noise for the first 100 miles while the pads seat.", "Check the fluid level once more after a week.", {"text": "Performance compounds can dust and squeal more than OE. That''s the trade for the bite.", "only": ["perf"]}], "disagreements": [{"topic": "Rotor set screw torque", "pos": "FCP Euro lists 4 Nm; owner transcriptions of the Mk7 manual list 8 Nm.", "call": "Either is fine. It only holds the rotor in place until the wheel goes on. Snug it and don''t strip the T30."}, {"topic": "Reusing front carrier bolts", "pos": "Some kits treat them as one-time use. VW''s spec is a plain 200 Nm with no angle, and forum members reuse them.", "call": "Reuse clean, undamaged bolts. Replace any with rusty or stretched-looking threads; they''re about $10."}, {"topic": "Rotors with every pad change", "pos": "Some shops resurface rotors to save money.", "call": "Replace them. There''s only about 3 mm of wear allowance, so resurfaced rotors start close to the limit."}], "sources": ["FCP Euro, The Definitive Guide To VW Mk7 GTI Brakes (2021): systems, pad differences, limits, torque list", "mygolfmk7.com Mk7 GTI torque table", "golfmk7.com forum: front brake caliper bolts thread (Golf R / GTI spec)", "onemandiy.com: 2016 Mk7 Golf disc brake DIY with 2015 manual torques", "ECS Tuning, Deutsche Auto Parts, NGP Racing and APR fitment listings (rotor sizes, 2019–2021 340 mm fitment)"], "embeds": [{"id": "iIVuKRRr2CU", "note": "FCP Euro walks through the Mk7 GTI brake systems."}]}'::jsonb);
insert into guides (id, content) values ('brake-fluid-mk7', '{"title": "Brake fluid flush & stainless lines", "category": "Brakes", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Same procedure on the Mk7 Golf and Golf R. Line kits are specific to base, Performance-brake and Golf R cars.", "heroId": "mk7-fluid-hero", "heroCap": "VW''s bleed order with a pressure bleeder. Manual cars also bleed the clutch.", "variants": {"questions": [{"question": "What are you doing?", "options": [{"id": "flush", "label": "Fluid flush only", "when": "Routine every two years, or after hard track use.", "oeOnly": true}, {"id": "lines", "label": "Flush plus stainless lines", "when": "All four flexible hoses replaced, then a full bleed."}]}, {"question": "Which gearbox?", "hint": "Manual cars share the brake reservoir with the clutch, so the clutch gets bled too.", "options": [{"id": "manual", "label": "Manual", "when": "Three pedals."}, {"id": "dsg", "label": "DSG", "when": "Two pedals."}]}]}, "glance": {"why": "Brake fluid soaks up water and the pedal goes soft. Fresh fluid costs $25 and an hour.", "timeFirst": "1–1.5 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$25–280", "risk": "Letting the reservoir run dry puts air in the ABS unit.", "note": "Low end is fluid only. Line kits add $200–250. Add an hour for lines."}, "lifespan": {"headline": ["3 years from new, then every 2 years"], "detail": "Brake fluid absorbs moisture from the air, which lowers its boiling point and makes the pedal soft when it gets hot.", "factors": ["Track days", "Humid climate", "Racing fluids (shorter intervals)"], "inspect": [{"text": "Rubber hoses: look for cracks at every pad change", "only": ["flush"]}], "confidence": {"level": "high", "n": 1, "note": "Interval and capacity from FCP Euro''s Mk7 brake guide."}}, "should": {"yesIf": ["It''s been two years or more since the last flush", "The fluid in the reservoir is dark amber or brown", "The pedal goes soft after hard driving", {"text": "You want a firmer, more consistent pedal, especially with performance pads", "only": ["lines"]}, {"text": "The rubber hoses are cracked or bulge when someone presses the pedal", "only": ["lines"]}], "codes": [], "notes": ["System capacity is about 1.2 litres. A pressure bleeder makes this a one-person job.", {"text": "Line kits differ between base and Performance-brake cars. Check your front rotor size before ordering.", "only": ["lines"]}], "confidence": {"level": "high", "n": 2, "note": "FCP Euro''s Mk7 guide and Neuspeed''s fitment notes."}}, "parts": [{"tier": "oem", "name": "DOT 4 brake fluid, 1 litre", "note": "Pentosin Super DOT 4 or ATE Type 200. Never reuse what comes out.", "price": "$15–30", "only": ["flush"], "links": [{"store": "FCP Euro", "url": "https://www.fcpeuro.com/products/super-dot-4-brake-fluide-1-2-liter-1204114-1204115"}]}, {"tier": "oem", "name": "DOT 4 brake fluid, 2 litres", "note": "Buy extra: you lose fluid each time a hose comes off.", "price": "$30–55", "only": ["lines"], "links": [{"store": "FCP Euro", "url": "https://www.fcpeuro.com/products/super-dot-4-brake-fluide-1-2-liter-1204114-1204115"}]}, {"tier": "aftermarket", "name": "Stainless brake line kit (4 lines)", "note": "Order the kit for your brakes: base (312 mm) or Performance (340 mm). Includes banjo bolts and copper washers.", "price": "$200–250", "only": ["lines"]}, {"tier": "oe", "name": "Copper crush washers", "note": "If your kit doesn''t include them: two per banjo bolt, always new.", "price": "$1 each", "only": ["lines"]}], "aftermarket": [{"name": "Motul RBF 600 or Castrol SRF", "note": "Racing fluids for track cars. Higher boiling point, but flush more often. SRF is the most expensive.", "price": "$20–80 per litre"}, {"name": "Neuspeed stainless lines", "note": "PTFE core, stainless braid, PVC cover, DOT certified. Separate kits for base and Performance-brake cars.", "price": "$200–250", "only": ["lines"], "links": [{"store": "Neuspeed (base)", "url": "https://neuspeed.com/en-ca/products/neuspeed-sport-brake-lines-hvw4411"}, {"store": "Black Forest (PP)", "url": "https://blackforestindustries.com/products/stainless-steel-brake-lines-gti-mk7-performance-pack"}]}, {"name": "ECS Exact-Fit stainless lines", "note": "DOT-compliant, pressure-tested to 3,000 psi; comes with banjo bolts, copper washers and new bracket clips.", "only": ["lines"]}, {"name": "StopTech stainless lines", "note": "DOT approved, sold alone or in StopTech''s axle packs with pads and rotors.", "only": ["lines"]}], "tools": [{"name": "Pressure bleeder with VW cap adapter", "note": "Motive-style. Makes it a one-person job.", "price": "$70"}, {"name": "Clear bleed hose and catch bottle", "price": "$10"}, {"name": "11 mm and 9 mm wrenches", "note": "Caliper bleed screws and the clutch slave bleed screw.", "price": "$10"}, {"name": "Syringe or turkey baster", "note": "Empty the reservoir before you start.", "price": "$5"}, {"name": "Jack and stands", "note": "Rear bleed screws are easiest with the wheels off.", "price": "$120"}, {"name": "Line (flare-nut) wrench to fit the hard-line nuts", "note": "An open-end wrench rounds them off.", "price": "$15", "only": ["lines"]}, {"name": "Torque wrench", "note": "Banjo bolts.", "price": "$40", "only": ["lines"]}, {"name": "Hose clamp pliers or a brake pedal holder", "note": "Limits fluid loss while a hose is off.", "price": "$15", "only": ["lines"]}, {"name": "Rags and a water spray bottle", "note": "Brake fluid strips paint. Rinse any spill with water straight away.", "price": "$5"}], "before": ["Brake fluid strips paint. Cover the fender and have water handy.", "Use a fresh, sealed bottle. Opened fluid has already started absorbing moisture.", {"text": "Do the lines with the bleeder unpressurised and the reservoir cap on. That slows what drains out of an open hose.", "only": ["lines"]}, {"text": "Find the clutch slave bleed screw on top of the gearbox before you start; you''ll want a longer hose for it.", "only": ["manual"]}], "chapters": [{"id": "prep", "title": "Prep"}, {"id": "lines", "title": "Fit the lines", "blurb": "One corner at a time, front then rear."}, {"id": "bleed", "title": "Bleed", "blurb": "Every corner in VW''s order, then the clutch on manual cars."}, {"id": "finish", "title": "Finish"}], "steps": [{"chapter": "prep", "title": "Empty and refill the reservoir", "blocks": [{"t": "text", "b": "The reservoir is at the back of the engine bay on the driver''s side. Pull out as much old fluid as you can with the syringe, then refill to MAX with new fluid. Everything that flows from here on pushes new fluid through."}]}, {"chapter": "prep", "title": "Lift the car and pull the wheels", "blocks": [{"t": "text", "b": "Get all four corners on stands, or do one axle at a time. Pop the rubber caps off the bleed screws and loosen each one a little, then snug it, so nothing is seized when you need it."}]}, {"chapter": "lines", "only": ["lines"], "title": "Swap a front line", "caution": true, "blocks": [{"t": "ill", "id": "mk7-fluid-line", "cap": "Hard line and flare nut, bracket clip, hose, banjo at the caliper."}, {"t": "text", "b": "Clamp the old hose lightly if you have hose clamp pliers. Undo the flare nut where the hard line meets the hose with the line wrench while holding the hose fitting still. Slide out the retaining clip and free the hose from its bracket."}, {"t": "text", "b": "Undo the banjo bolt at the caliper and remove the old hose."}, {"t": "text", "b": "Fit the new line with a new copper washer on each side of the banjo. Route it the same way as the old one, with no twist."}, {"t": "torque", "label": "banjo bolt", "nm": 35, "c": {"level": "medium", "n": 1, "note": "ECS''s spec for their Mk7 Exact-Fit kit. Your kit''s own instructions win if they differ."}}, {"t": "text", "b": "Thread the hard line into the hose fitting by hand first, then snug it with the line wrench to about 14–19 Nm. Refit the clip."}, {"t": "warn", "b": "Turn the steering to full lock both ways and check the line doesn''t stretch or rub on anything."}]}, {"chapter": "lines", "only": ["lines"], "title": "Swap a rear line", "blocks": [{"t": "text", "b": "Same sequence as the front: flare nut, clip, banjo. Rear hoses are shorter and less fiddly. Check the line clears the spring and arms with the suspension hanging."}]}, {"chapter": "lines", "only": ["lines"], "title": "Check every fitting", "blocks": [{"t": "text", "b": "Before bleeding, go round all four corners and check each banjo bolt and flare nut is tight and each clip is in."}]}, {"chapter": "bleed", "title": "Pressurise and bleed each corner", "timeSink": true, "blocks": [{"t": "ill", "id": "mk7-fluid-hero", "cap": "Left front, right front, left rear, right rear."}, {"t": "text", "b": "Fit the pressure bleeder to the reservoir and pump it to about 1 bar (15 psi). Check for leaks at the cap."}, {"t": "text", "b": "Start at the left front. Push the clear hose onto the bleed screw, open it a quarter turn and let it run until the fluid comes through clear with no bubbles: about 200 ml at each front. Close it and move on."}, {"t": "text", "b": "Then right front, left rear and right rear. The rears take about 300 ml each."}, {"t": "text", "b": "With new lines fitted, let each corner run longer: there''s a full hose of air to push out.", "only": ["lines"]}, {"t": "warn", "b": "Check the bleeder''s fluid level between corners. If the reservoir runs dry, air gets into the ABS unit, and that takes a scan tool to fix."}, {"t": "note", "b": "Tighten the bleed screws snug, not hard. They''re small and hollow and will snap."}]}, {"chapter": "bleed", "only": ["manual"], "title": "Bleed the clutch slave", "blocks": [{"t": "text", "b": "The clutch slave bleed screw is on top of the gearbox, in front of the shifter linkage. Take off the engine cover if it''s in the way. Fit a longer hose, open the screw and let about 50 ml run out."}, {"t": "text", "b": "Close it, press the clutch pedal 10–15 times, open it again for another 50 ml, and close it. Pump the clutch a few times to check it feels normal."}, {"t": "warn", "b": "Don''t let the clutch pedal snap back to the floor while the screw is open. Lower it gently with your hand."}]}, {"chapter": "bleed", "title": "Check the pedal, bleed again if it''s soft", "blocks": [{"t": "ill", "id": "mk7-fluid-check", "cap": "Clear amber with no bubbles means that corner is done."}, {"t": "text", "b": "Release the bleeder pressure and press the brake pedal. It should be high and firm."}, {"t": "text", "b": "If it''s soft, do VW''s assisted bleed: a helper presses the pedal hard and holds it, you open the bleed screw, they push it to the floor, you close it, then they let it up slowly. Do that five times per corner in the same order."}, {"t": "note", "b": "If the pedal is still soft after that, air may have reached the ABS unit. VCDS or OBDeleven can run the ABS bleed routine. Never run it with the brakes in pieces."}]}, {"chapter": "finish", "title": "Set the level and check for leaks", "blocks": [{"t": "text", "b": "Release the bleeder slowly so it doesn''t spray, remove it, and set the fluid level to MAX. Refit the bleed caps."}, {"t": "text", "b": "Hold firm pressure on the brake pedal for 10–15 seconds while someone looks at each bleed screw and fitting."}, {"t": "text", "b": "Look closely at every banjo and flare nut you touched.", "only": ["lines"]}]}, {"chapter": "finish", "title": "Test drive", "caution": true, "blocks": [{"t": "text", "b": "Start the engine and check the pedal again with the brake booster working. Then a few gentle stops in an empty lot before any real braking."}]}], "alsoReplace": [{"name": "Pads and rotors", "why": "If they''re close to due, do them first. Pushing pistons back pushes old fluid up into the reservoir that you''re about to flush out."}, {"name": "Rubber bleed screw caps", "why": "Cheap, and missing ones let screws seize.", "only": ["flush"]}], "check": {"tab": "Is it done?", "title": "Is it done?", "illId": "mk7-fluid-check", "illCap": "Close each bleed screw once it runs clear with no bubbles.", "rows": [{"see": "Clear fluid, no bubbles at all four corners, firm pedal", "means": "The system is full of new fluid.", "do": "Set the level, check for leaks, test drive."}, {"see": "Pedal soft or long but it doesn''t sink", "means": "Air still in a caliper or line.", "do": "Do the assisted bleed: five pumps per corner in order."}, {"see": "Pedal slowly sinks under steady pressure", "means": "A leak at a fitting, or a failing master cylinder.", "do": "Don''t drive. Check every fitting you touched, then the master cylinder."}], "c": {"level": "high", "n": 2, "note": "VW workshop procedure excerpt on vwvortex and a Project GTi bleed guide."}}, "aftercare": ["Note the date on the reservoir with a paint pen or in your records.", {"text": "Recheck every fitting for weeping after 100 miles.", "only": ["lines"]}, "Check the fluid level after a week."], "disagreements": [{"topic": "Bleed order", "pos": "VW''s procedure goes left front, right front, left rear, right rear. Many DIY guides start furthest from the master cylinder (right rear).", "call": "Follow VW''s order with a pressure bleeder. Either works if you never let air in, but VW''s is the one the system was designed around."}, {"topic": "Bleeder pressure", "pos": "VW workshops run about 2 bar (30 psi). DIY guides use 10–15 psi.", "call": "1 bar (15 psi) on a hobby bleeder: plenty of flow with less risk of a cap leak."}, {"topic": "Clutch first or last", "pos": "Guides disagree on whether to bleed the clutch first or last.", "call": "Last. It shares only the reservoir, so the order doesn''t matter much."}], "sources": ["FCP Euro, The Definitive Guide To VW Mk7 GTI Brakes (2021): fluid type, capacity, interval, lines", "VW workshop bleed procedure (Mk5 excerpt) via vwvortex: order, pressure, assisted bleed", "Micks Garage Project GTi: How to Bleed Your Brakes (volumes, clutch slave, ABS routine)", "golfmk6.com DIY: stainless lines and fluid flush", "ECS Tuning Exact-Fit Mk7 line kit (banjo torque), Neuspeed Mk7 fitment notes", "Ross-Tech wiki, Golf VII ABS: don''t run basic settings with the brakes disassembled"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('dsg-service-mk7', '{"title": "DSG fluid & filter service", "category": "Drivetrain", "fits": "2015–2021 GTI with DSG (6-speed DQ250 or 7-speed DQ381)", "alsoFits": "DQ250: Mk7 Golf R and earlier GTIs use the same filter and fluid. DQ381: 2018+ Golf R, 2019+ GLI, 8V.5 A3/S3.", "heroId": "mk7-dsg-hero", "heroCap": "Filter, drain plug and, on the 7-speed, the extra mechatronic plug.", "variants": {"questions": [{"question": "Which DSG do you have?", "hint": "Put it in manual mode and count the gears, or go by model year.", "options": [{"id": "dq250", "label": "6-speed (DQ250)", "when": "2015–2018 GTI."}, {"id": "dq381", "label": "7-speed (DQ381)", "when": "2019–2021 GTI."}]}]}, "glance": {"why": "The fluid runs the clutches, cools them and works the hydraulics. It''s the one service a wet DSG can''t skip.", "timeFirst": "2–2.5 hr", "timeRepeat": "1.5 hr", "difficulty": 3, "cost": "$150–250", "risk": "Checking the level outside 35–45 °C gets the fill wrong.", "note": "You need a fill adapter and a way to read gearbox temperature: a scan tool or an infrared thermometer."}, "lifespan": {"headline": ["Every 40,000 miles"], "detail": "VW''s interval for wet-clutch DSGs. Some DQ381 schedules list longer, but specialists change it early: the 7-speed is known to judder on old fluid, and some left the factory underfilled.", "factors": ["Tuned engine", "Launch control", "Stop-and-go heat", "Track days"], "confidence": {"level": "medium", "n": 3, "note": "VW dealer and specialist guidance agree on about 40,000 miles; DQ381 early-change advice comes from Australian and US specialists."}}, "should": {"yesIf": ["It''s been 40,000 miles or four years since the last service", "You see judder or hesitation pulling away slowly", "Shifts have gone harsh or slow when warm", {"text": "You''ve had it tuned, or you''re about to", "only": ["dq381"]}], "codes": [], "notes": ["Car must be level for the final check: all four wheels on stands at the same height, or on a lift.", {"text": "The 7-speed''s filter lies on its side at the front of the gearbox behind the downpipe, and oil runs out over the case when it comes off. Pack rags under it.", "only": ["dq381"]}], "confidence": {"level": "high", "n": 3, "note": "ECS Tuning and FCP Euro DSG procedures, VW workshop manual extract for the 0GC gearbox."}}, "parts": [{"tier": "oe", "name": "DSG fluid G 052 182 A2, 6 litres", "note": "About 5.5 litres goes in; the spare covers the level check.", "price": "$90–130", "only": ["dq250"]}, {"tier": "oe", "name": "DSG fluid G 055 529 A2, 7 litres", "note": "Check against your VIN before ordering; VW has revised wet-DSG fluid part numbers. About 6 litres goes in.", "price": "$110–160", "only": ["dq381"]}, {"tier": "oe", "name": "DSG filter", "pn": "02E 305 051 C", "note": "Vertical cartridge under the 24 mm cap.", "price": "$20–30", "only": ["dq250"], "links": [{"store": "ECS (VAICO kit)", "url": "https://www.ecstuning.com/b-vaico-parts/dsg-transmission-service-kit-without-service-tool-featuring-vaico-fluid-and-filter/02e398000/"}]}, {"tier": "oe", "name": "DSG filter", "pn": "0GC 325 183 D", "note": "Also listed as 0GC 325 183 A on earlier cars.", "price": "$50–60", "only": ["dq381"], "links": [{"store": "NGP Racing", "url": "https://store.ngpracing.com/products/genuine-vw-audi-dq381-dsg-filter-0gc325183d"}]}, {"tier": "oe", "name": "Filter housing O-ring", "pn": "N 910 845 01", "note": "Usually in the filter box.", "price": "$5"}, {"tier": "oe", "name": "Drain plug washer", "pn": "N 043 809 2", "price": "$2"}, {"tier": "oe", "name": "Mechatronic drain plug washer", "pn": "N 013 813 2", "price": "$2", "only": ["dq381"]}], "aftermarket": [{"name": "DSG software (TCU tune)", "note": "Faster shifts, higher clamping, holds gears longer. Needs a matching ECU tune; never flash it on a stock ECU.", "price": "$500–600", "links": [{"store": "IE DQ381 tune", "url": "https://acmtechnik.com/products/ie-vw-mk7-audi-8v-dsg-dq381-transmission-tune-fits-2019-gti-gli-golf-r-s3-a3-2019-tts"}]}, {"name": "Liqui Moly or VAICO service kits", "note": "Fluid, filter and seals in one box, at a lower price than genuine."}], "tools": [{"name": "DSG fill adapter and pump or pressure bottle", "note": "Threads into the drain hole. Keep a pressure bottle at 5–10 psi.", "price": "$40–80"}, {"name": "14 mm and 8 mm hex bits", "note": "Drain plug, and the overflow tube inside it.", "price": "$15"}, {"name": "24 mm socket on a long extension", "note": "Filter cap.", "price": "$10", "only": ["dq250"]}, {"name": "Scan tool or infrared thermometer", "note": "VCDS or OBDeleven reads gearbox oil temperature; an IR thermometer on the pan is the fallback.", "price": "$20–80"}, {"name": "Small ¼\" torque wrench", "note": "The overflow tube is 3 Nm: barely more than finger tight.", "price": "$40"}, {"name": "8-litre drain pan, rags, gloves", "price": "$20"}, {"name": "Four jack stands at the same height, or a lift", "price": "$80"}], "before": ["Start with the car cold or barely warm. The level check needs the gearbox to come up through 35 °C with you ready.", "Lift the car level and leave it there for the whole job.", {"text": "Have the intake pipe off and rags packed around the filter before you touch it.", "only": ["dq381"]}], "chapters": [{"id": "filter", "title": "Filter"}, {"id": "drain", "title": "Drain"}, {"id": "fill", "title": "Fill and set the level"}], "steps": [{"chapter": "filter", "only": ["dq250"], "title": "Remove the airbox", "blocks": [{"t": "text", "b": "Unplug the airflow sensor, pull the small hoses off the bottom of the airbox, undo its heat-shield fastener and lift the box out. The filter cap is on top of the gearbox underneath."}]}, {"chapter": "filter", "only": ["dq250"], "title": "Change the filter", "blocks": [{"t": "text", "b": "Undo the 24 mm cap and lift it up and out towards the passenger side. Pull out the cartridge, put a rag in the opening, and fit the new O-ring lightly oiled with new fluid."}, {"t": "text", "b": "Drop in the new cartridge and start the cap by hand. The threads are plastic."}, {"t": "torque", "label": "filter cap", "nm": 20, "c": {"level": "high", "n": 3, "note": "ECS Tuning, FCP Euro and Blau Parts DQ250 procedures."}}, {"t": "text", "b": "Refit the airbox."}]}, {"chapter": "filter", "only": ["dq381"], "title": "Change the filter", "caution": true, "blocks": [{"t": "text", "b": "Remove the intake pipe for access. The filter lies on its side at the front of the gearbox behind the downpipe, under a heat shield. Pack rags underneath: oil runs out over the case when it opens."}, {"t": "text", "b": "Unscrew the filter, fit the new O-ring lightly oiled and screw the new filter in."}, {"t": "torque", "label": "filter", "nm": 50, "c": {"level": "single", "n": 1, "note": "VW 0GC workshop manual as quoted on seatcupra.net. Higher than the DQ250''s 20 Nm, which most DIY guides copy by mistake."}}]}, {"chapter": "drain", "title": "Drain the gearbox", "timeSink": true, "blocks": [{"t": "ill", "id": "mk7-dsg-level", "cap": "The overflow tube sits inside the drain hole and sets the oil height."}, {"t": "text", "b": "Under the car, remove the 14 mm hex drain plug. Most of the oil comes out."}, {"t": "text", "b": "Reach up inside the hole with the 8 mm hex and unscrew the plastic overflow tube. The rest drains out. Refit the tube when it stops."}, {"t": "torque", "label": "overflow tube", "nm": 3, "c": {"level": "high", "n": 2, "note": "ECS Tuning and FCP Euro."}}]}, {"chapter": "drain", "only": ["dq381"], "title": "Drain the mechatronic unit", "blocks": [{"t": "text", "b": "The 7-speed has a second, smaller drain plug on the mechatronic housing. VW''s procedure drains it too. Remove it, let it empty and refit it with a new washer, tightened to the figure on your kit''s instruction sheet."}]}, {"chapter": "fill", "title": "Fill through the drain hole", "blocks": [{"t": "text", "b": "Thread the fill adapter into the drain hole and pump in new fluid before starting the engine."}, {"t": "text", "b": "About 5.5 litres goes in first.", "only": ["dq250"]}, {"t": "text", "b": "About 6 litres goes in first.", "only": ["dq381"]}, {"t": "warn", "b": "If you use a pressurised bottle, keep it at 5–10 psi. They can burst."}]}, {"chapter": "fill", "title": "Set the level at 35–45 °C", "caution": true, "blocks": [{"t": "text", "b": "Leave the adapter in. Start the engine and, with your foot on the brake, move through every selector position for 3–5 seconds each."}, {"t": "text", "b": "Watch the gearbox temperature. Between 35 and 45 °C, disconnect the fill hose and let the excess run out of the adapter. When it slows to a steady drip, the level is right. If nothing comes out, pump more in until it does."}, {"t": "text", "b": "With the engine still running, take out the adapter and fit the drain plug with a new washer."}, {"t": "torque", "label": "drain plug", "nm": 45, "c": {"level": "high", "n": 3, "note": "ECS Tuning, FCP Euro, Blau Parts DQ250 procedures."}, "only": ["dq250"]}, {"t": "text", "b": "Tighten the drain plug to the figure on your kit''s sheet.", "only": ["dq381"]}, {"t": "warn", "b": "Above 45 °C the oil has expanded and you''ll underfill it. If you overshoot, let it cool and start the check again."}]}, {"chapter": "fill", "title": "Reset the clutch adaptation", "blocks": [{"t": "text", "b": "Optional but worth it if you had judder: run the DSG basic settings (clutch adaptation) with VCDS or OBDeleven so the gearbox relearns its bite points on fresh fluid."}, {"t": "note", "b": "If judder stays after fresh fluid and an adaptation, ask a dealer to check for newer gearbox software. VW released updates for low-speed driveability.", "only": ["dq381"]}]}], "alsoReplace": [{"name": "Engine oil and filter", "why": "Car''s already in the air with a drain pan under it."}, {"name": "Intake pipe clamps", "why": "If the factory clamps fought you, swap in new ones before they leak boost.", "only": ["dq381"]}], "check": {"tab": "Is the level right?", "title": "Is the level right?", "illId": "mk7-dsg-level", "illCap": "Steady drip from the adapter, between 35 and 45 °C.", "rows": [{"see": "A steady drip at 35–45 °C", "means": "Oil is at the top of the overflow tube.", "do": "Plug it and you''re done."}, {"see": "Nothing comes out at 35 °C", "means": "Underfilled.", "do": "Pump more in until it runs, then let it settle to a drip."}, {"see": "Judder or flare after the service", "means": "The gearbox is still adapting, or the level is off.", "do": "Run a clutch adaptation, then recheck the level if it persists."}], "c": {"level": "high", "n": 3, "note": "ECS Tuning, FCP Euro, and a VW-dealer service guide."}}, "aftercare": ["Drive gently for the first 20 miles while the adaptation settles.", "Check under the car for drips at the drain plug and filter the next day.", "Note the mileage: next one in 40,000."], "disagreements": [{"topic": "DQ381 interval", "pos": "Some schedules list a longer interval for the 7-speed; specialists say 40,000 miles or sooner.", "call": "40,000 miles. Fluid is cheap and the 7-speed is known to judder on old fluid."}, {"topic": "DQ381 filter torque", "pos": "Most videos use the DQ250''s 20 Nm. VW''s 0GC manual lists 50 Nm.", "call": "50 Nm, from the manual. Different filter, different spec."}, {"topic": "Scan tool or thermometer", "pos": "Shops insist on a scan tool. ECS says an IR thermometer on the pan works when you don''t have one.", "call": "Scan tool if you can. An IR reading on the pan gets you close; err to the low end of the window."}], "sources": ["ECS Tuning: Volkswagen DSG transmission fluid service (filter, overflow tube, fill, temps, torques)", "FCP Euro: Audi & VW DSG transmission service DIY (02E)", "Blau Parts: VW Golf DSG 6-speed fluid and filter change", "seatcupra.net: DQ381 service thread quoting VW''s 0GC workshop manual (filter 50 Nm, mechatronic drain, parts list)", "golfmk7.com: DQ381 service thread (filter behind the downpipe on 2019+ GTI)", "NGP Racing DQ381 filter fitment; VAG Parts and Gearbox Insider on DQ381 service and judder"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('clutch-mk7', '{"title": "Clutch & flywheel replacement", "category": "Drivetrain", "fits": "2015–2021 GTI with 6-speed manual", "alsoFits": "FCP Euro''s procedure covers the Mk7 Golf R manual too; it has extra all-wheel-drive steps not covered here.", "heroId": "mk7-clutch-hero", "heroCap": "Engine side to gearbox side, with the bolts that must be new.", "variants": {"questions": [{"question": "What''s going in?", "options": [{"id": "oe", "label": "OE-spec clutch and flywheel", "when": "Worn clutch on a stock or lightly tuned car.", "oeOnly": true}, {"id": "ttrs", "label": "TT RS pressure plate (OEM+)", "when": "Audi TT RS pressure plate with a 240 mm Sachs disc. Stock feel, much more clamp."}, {"id": "perf", "label": "Performance clutch kit", "when": "Sachs Performance, South Bend and similar, for bigger tunes."}]}, {"question": "Does your car have the front limited-slip differential?", "hint": "Performance Package cars and Mk7.5 (2018+) GTIs do. It''s a finned housing with two connectors at the right-side axle.", "options": [{"id": "lsd", "label": "Yes, it has the LSD", "when": "That unit has to come out before the gearbox."}, {"id": "open", "label": "No, open differential", "when": "Early base cars without the Performance Package."}]}]}, "glance": {"why": "A gearbox-out job. Do it once, do it right, and replace everything the clutch touches while you''re in there.", "timeFirst": "10–14 hr", "timeRepeat": "6–8 hr", "difficulty": 4, "cost": "$700–1,800", "risk": "Stretch bolts everywhere. Reused flywheel or mount bolts are what come loose.", "note": "Times assume a helper for the gearbox and LSD. FCP Euro quotes about six hours with all the tools and a friend or two."}, "lifespan": {"headline": ["Replace it when it slips, not by mileage"], "detail": "Clutch life depends on driving and on power. The factory friction material wasn''t meant for much more than stock torque and starts to slip once a tune raises it.", "factors": ["ECU tune", "Launches and hard shifts", "Riding the pedal", "City driving"], "confidence": {"level": "medium", "n": 1, "note": "FCP Euro''s Mk7 clutch DIY. No reliable mileage figure exists."}}, "should": {"yesIf": ["The revs rise in a high gear under load but the car doesn''t pick up speed", "The bite point has crept to the top of the pedal", "You smell a hot, burning clutch after normal driving", "Gears are hard to engage and bleeding the clutch didn''t fix it", {"text": "You''re planning a tune past the stock clutch''s limit", "only": ["ttrs", "perf"]}], "codes": [], "notes": ["Squeal with the pedal pressed often points at the release bearing; it gets replaced in this job anyway.", {"text": "The TT RS pressure plate is rated for about 430 lb-ft per Deutsche Auto Parts, more than almost any non-big-turbo Mk7 makes. The TT RS disc doesn''t fit; you need the 240 mm Sachs disc.", "only": ["ttrs"]}], "confidence": {"level": "high", "n": 2, "note": "FCP Euro''s Mk7 clutch DIY; Deutsche Auto Parts TT RS clutch guide."}}, "parts": [{"tier": "oem", "name": "Clutch kit: pressure plate and disc", "note": "Sachs or LuK, matched to the 6-speed.", "price": "$350–500", "only": ["oe"]}, {"tier": "oem", "name": "Dual-mass flywheel", "note": "Sachs or LuK. Replace it unless it passes the play test and has no heat spots.", "price": "$500–800", "only": ["oe"]}, {"tier": "oem", "name": "Audi TT RS pressure plate", "note": "The OEM+ upgrade.", "price": "$350–450", "only": ["ttrs"]}, {"tier": "oem", "name": "Sachs 240 mm clutch disc", "note": "Required. The TT RS disc won''t work.", "price": "$150–250", "only": ["ttrs"]}, {"tier": "aftermarket", "name": "Performance clutch and flywheel kit", "note": "Pick a kit from the aftermarket list. Check its torque rating against your tune.", "price": "$900–1,500", "only": ["perf"], "links": [{"store": "FCP Euro (Sachs Performance)", "url": "https://www.fcpeuro.com/products/vw-clutch-kit-sachs-performance-883089000126"}]}, {"tier": "oem", "name": "Release bearing (concentric slave)", "pn": "0A5 141 671 N", "note": "LuK. Cheap, and inside the bell housing: replace it every time.", "price": "$35", "links": [{"store": "FCP Euro", "url": "https://www.fcpeuro.com/products/vw-clutch-release-bearing-luk-0a5141671n"}]}, {"tier": "oe", "name": "Flywheel bolts (set)", "note": "Stretch bolts. Always new.", "price": "$20–30"}, {"tier": "oe", "name": "Pressure plate bolts (6)", "note": "Always new.", "price": "$10–15"}, {"tier": "oe", "name": "Transmission mount bolts (6)", "note": "60 Nm + 90°: new.", "price": "$15–25"}, {"tier": "oe", "name": "Dogbone mount bolts (3)", "note": "Torque-plus-angle: new.", "price": "$10–15"}, {"tier": "oe", "name": "Rear main seal", "pn": "06K 103 171 G", "note": "Highly recommended while the flywheel is off.", "price": "$40–60"}, {"tier": "oe", "name": "Manual gearbox oil, 3 litres", "note": "VW-spec oil to match your gearbox; it takes about 2.5 litres.", "price": "$45–75"}, {"tier": "oe", "name": "Haldex fluid, 1 litre", "note": "The LSD unit has its own oil.", "price": "$25–35", "only": ["lsd"]}, {"tier": "oe", "name": "DOT 4 brake fluid, 500 ml", "note": "The clutch shares the brake reservoir and needs bleeding.", "price": "$10"}], "aftermarket": [{"name": "Sachs Performance clutch and flywheel", "note": "What FCP Euro fitted in their DIY car. Just under $1,500 as a kit.", "price": "about $1,500", "only": ["perf+lsd", "perf+open"], "links": [{"store": "FCP Euro", "url": "https://www.fcpeuro.com/products/vw-clutch-kit-sachs-performance-883089000126"}]}, {"name": "TT RS pressure plate + Sachs disc (OEM+)", "note": "Factory-quality parts with much more clamping force and near-stock pedal feel.", "only": ["oe+lsd", "oe+open", "perf+lsd", "perf+open"], "links": [{"store": "Deutsche Auto Parts guide", "url": "https://www.shopdap.com/blog/post/how-to-install-a-ttrs-clutch-on-a-mk7.html"}]}, {"name": "South Bend Stage 2 and 3 kits", "note": "Popular for bigger tunes; offered with the dual-mass flywheel or a single-mass one."}, {"name": "Single-mass flywheel", "note": "Lighter and quicker to rev, but adds gear rattle and vibration at idle. A trade for track cars more than daily drivers."}], "tools": [{"name": "Engine support bar", "note": "Holds the engine while the gearbox mount is off.", "price": "$80"}, {"name": "Floor jack with a gearbox cradle or a second jack", "price": "$150"}, {"name": "Triple-square bits: 10 mm and 12 mm", "note": "Axle bolts and flywheel bolts.", "price": "$25"}, {"name": "Hex bits: 4, 6 and 8 mm, plus long extensions", "note": "The 6 mm axle-cup bolts are deep inside the cups.", "price": "$30"}, {"name": "18, 16, 13, 21 mm sockets with swivels and wobble extensions", "price": "$40"}, {"name": "T25 and T30 Torx", "note": "Belly pan and charge pipe.", "price": "$10"}, {"name": "Flywheel holder", "note": "Or a bolt and steel strap rig through a bell housing hole.", "price": "$20"}, {"name": "VW clutch alignment tool", "note": "Use a proper one, not the plastic tube that comes in the box.", "price": "$25"}, {"name": "Torque wrench and angle gauge", "price": "$80"}, {"name": "Fluid pump", "note": "For gearbox oil and the LSD.", "price": "$20"}, {"name": "Pry bar and an extendable magnet", "price": "$20"}, {"name": "A helper", "note": "For the LSD unit and the gearbox itself."}], "before": ["Give yourself a full weekend and a level floor.", "Bag and label every bolt as it comes out. Bell housing bolts differ in length.", "Have every stretch bolt on hand before you start. Stores are closed when you find out.", {"text": "Have a drain pan wide enough for the LSD: its oil runs onto the subframe and off in several places.", "only": ["lsd"]}], "chapters": [{"id": "top", "title": "Engine bay"}, {"id": "under", "title": "Underneath"}, {"id": "lsd", "title": "LSD unit", "blurb": "Performance Package and Mk7.5 cars only."}, {"id": "out", "title": "Gearbox out"}, {"id": "clutch", "title": "Clutch and flywheel"}, {"id": "back", "title": "Back together"}, {"id": "fluids", "title": "Bleed, fill, finish"}], "steps": [{"chapter": "top", "title": "Intake, battery and tray out", "blocks": [{"t": "text", "b": "Remove the intake: one 4 mm hex on its heat shield, the 7 mm clamp at the turbo inlet, and the small hoses underneath. Then the battery (10 mm terminals, 13 mm clamp) and its tray (three bolts and a nut, plus two harness clips)."}]}, {"chapter": "top", "title": "Free the shift cables", "blocks": [{"t": "text", "b": "Under the tray, pry the front cable''s metal tabs up and release it; the other cable has plastic tabs. Undo the cable bracket''s three 13 mm bolts and push the cables aside."}]}, {"chapter": "top", "title": "Top bell housing bolts, clutch line, starter", "blocks": [{"t": "text", "b": "Loosen the charge pipe clamp and its T30 bolt and pull the pipe back far enough to reach the top two 18 mm bell housing bolts. Remove them."}, {"t": "text", "b": "Lift the locking tab on the clutch line at the slave and pull it off. Plug it with a cap or foam earplug and don''t touch the clutch pedal from here on."}, {"t": "text", "b": "Remove the ground strap nut (13 mm) and the top starter bolt (18 mm), and unplug the starter."}]}, {"chapter": "under", "title": "Belly pan off, drain the oils", "blocks": [{"t": "text", "b": "Wheels off, then the belly pan: eight T25 screws and two tabs into the bumper."}, {"t": "text", "b": "Loosen the gearbox fill plug first (8 mm hex), then remove the drain plug and let it empty."}, {"t": "text", "b": "Drain the LSD unit''s own oil with a long 8 mm hex.", "only": ["lsd"]}]}, {"chapter": "under", "title": "Starter and lower charge pipe out", "blocks": [{"t": "text", "b": "Remove the two 13 mm nuts on the starter and the remaining 18 mm bolt while holding the starter. Remove the lower charge pipe''s T30 bolt, loosen the elbow''s two 7 mm clamps, free the harness clips and pull the charge pipe out from above."}]}, {"chapter": "under", "title": "Disconnect the axles", "blocks": [{"t": "text", "b": "Remove the heat shield behind the right inner CV joint (two 8 mm nuts). Disconnect the sway bar end links (18 mm), then the axle-to-gearbox bolts on both sides (10 mm triple-square)."}, {"t": "text", "b": "Undo the three 16 mm ball-joint nuts each side, pull the control arm down and swing the hub out to clear the axle from the gearbox."}]}, {"chapter": "lsd", "only": ["lsd"], "title": "Remove the LSD unit", "caution": true, "timeSink": true, "blocks": [{"t": "ill", "id": "mk7-clutch-lsd", "cap": "Four bolts, a deep axle-cup bolt and two connectors."}, {"t": "text", "b": "Remove the 6 mm hex bolt deep in the centre of the right-side axle cup on long extensions; a magnet pulls it out. Unplug the unit''s two connectors and the oil level sensor, and unclip the oil pan harness."}, {"t": "text", "b": "Undo the four 16 mm bolts. The top two are blind: wobble extensions and a helper guiding from the engine bay. Remove the dogbone mount''s bolts to the engine."}, {"t": "text", "b": "Pry the engine forward while a helper pulls the unit out."}]}, {"chapter": "out", "title": "Left axle cup and remaining low bolts", "blocks": [{"t": "text", "b": "Remove the 18 mm engine-to-gearbox bolt and the 21 mm dogbone bolt. On the driver''s side, hold the axle cup still with a pry bar between two bolt holes and remove its 6 mm hex bolt."}, {"t": "text", "b": "Without the LSD, remove the right-side axle cup the same way, and remove the dogbone mount''s bolts to the engine.", "only": ["open"]}]}, {"chapter": "out", "title": "Support the engine and drop the gearbox", "caution": true, "timeSink": true, "blocks": [{"t": "text", "b": "Remove the engine cover, attach the support bar to the engine''s lifting tab and take the weight. Remove the gearbox mount: three 18 mm bolts to the bracket, two to the gearbox, and lift the bracket out."}, {"t": "text", "b": "Support the gearbox on the jack, remove the remaining 18 mm bell housing bolts, and work it off the dowels and out past the subframe. It takes twisting and patience."}, {"t": "warn", "b": "Keep the gearbox level as it comes off the input shaft. Letting it hang on the clutch damages the disc and the bearing."}]}, {"chapter": "clutch", "title": "Remove the pressure plate and flywheel", "blocks": [{"t": "text", "b": "Undo the six pressure plate bolts a little at a time in a criss-cross so it unloads evenly. Catch the disc."}, {"t": "ill", "id": "mk7-clutch-check", "cap": "Read the old parts before they go in the bin."}, {"t": "text", "b": "Lock the flywheel and remove its bolts with the 12 mm triple-square."}]}, {"chapter": "clutch", "title": "Rear main seal and flywheel", "caution": true, "blocks": [{"t": "text", "b": "If you''re replacing the rear main seal, do it now. Clean the crank face with brake cleaner."}, {"t": "text", "b": "Note the offset bolt hole on the crank and line the flywheel up with it. Start the new bolts by hand, snug them in a star pattern, then torque and angle with the flywheel locked."}, {"t": "torque", "label": "flywheel bolts", "nm": 60, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}, "note": "+ 90°"}]}, {"chapter": "clutch", "title": "Disc and pressure plate", "blocks": [{"t": "text", "b": "Degrease the flywheel and pressure plate friction faces. Check the disc''s hub marking for which side faces the gearbox, and centre it with the alignment tool."}, {"t": "text", "b": "Fit the pressure plate with new bolts, tightening in a criss-cross in stages."}, {"t": "torque", "label": "pressure plate bolts", "nm": 20, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}}, {"t": "note", "b": "TT RS plate: use the 240 mm Sachs disc and the six bolts from the parts list.", "only": ["ttrs"]}, {"t": "note", "b": "Follow your kit''s own torque and bolt instructions if they differ.", "only": ["perf"]}]}, {"chapter": "clutch", "title": "Replace and bench-bleed the release bearing", "blocks": [{"t": "text", "b": "On the gearbox, remove the release bearing''s three 9 mm bolts. Put the new bearing''s hose end in a cup of brake fluid and pump it until no bubbles come out. Cap it."}, {"t": "text", "b": "Fit it with a dab of threadlocker on each bolt."}, {"t": "torque", "label": "release bearing bolts", "nm": 12, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}}]}, {"chapter": "back", "title": "Gearbox back in", "caution": true, "timeSink": true, "blocks": [{"t": "text", "b": "Lift the gearbox in and wiggle it onto the dowels until it sits flush against the engine all the way round. Only then start the bell housing bolts."}, {"t": "warn", "b": "Never use the bolts to pull the gearbox in. If it won''t go flush, the input shaft isn''t lined up with the disc."}, {"t": "text", "b": "Refit the gearbox mount bracket with new bolts, then remove the support bar."}, {"t": "torque", "label": "gearbox mount and bracket bolts", "nm": 60, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}, "note": "+ 90°"}]}, {"chapter": "back", "title": "Axle cups and LSD", "blocks": [{"t": "text", "b": "Push the left axle cup in and fit its bolt, holding the cup still with the pry bar."}, {"t": "torque", "label": "axle cup bolts", "nm": 33, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}}, {"t": "text", "b": "Fit the bell housing bolt next to the LSD, then slide the LSD unit past the subframe, seat it, fit its four 16 mm bolts and the right axle-cup bolt.", "only": ["lsd"]}, {"t": "text", "b": "Fit the right axle cup the same way as the left.", "only": ["open"]}]}, {"chapter": "back", "title": "Axles, ball joints, end links", "blocks": [{"t": "text", "b": "Bolt both axles to the cups."}, {"t": "torque", "label": "axle bolts", "nm": 70, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}}, {"t": "text", "b": "Fit the ball joints with new nuts."}, {"t": "torque", "label": "ball joint nuts", "nm": 40, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}, "note": "+ 40°"}, {"t": "torque", "label": "sway bar end link nuts", "nm": 65, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}}, {"t": "text", "b": "Plug the LSD connectors and the oil level sensor back in and clip the harness to the pan.", "only": ["lsd"]}]}, {"chapter": "back", "title": "Starter, cables, charge pipe, dogbone", "blocks": [{"t": "text", "b": "Fit the top bell housing bolts, the shift cable bracket and both cables, including the metal locking tab. Fit the starter, its bracket nut and connectors, the charge pipe, elbow and all harness clips."}, {"t": "text", "b": "Refit the dogbone mount with new bolts: rear bolt first, then the front two. The longer 16 mm bolt goes in the middle."}, {"t": "torque", "label": "dogbone front bolts", "nm": 50, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}, "note": "+ 90°"}, {"t": "torque", "label": "dogbone rear bolt", "nm": 100, "c": {"level": "high", "n": 1, "note": "FCP Euro''s Mk7 GTI / Golf R clutch DIY torque list."}, "note": "+ 90°"}]}, {"chapter": "fluids", "title": "Bleed the clutch", "blocks": [{"t": "text", "b": "Push the clutch line onto the bearing until it clicks and close the lock tab. Fit a bleed hose to the bleed nipple on the line (9 mm), open it and let gravity push fluid through from the reservoir. Close it, pump the pedal a few times, crack it open again, and repeat until the pedal feels normal."}]}, {"chapter": "fluids", "title": "Fill the gearbox", "blocks": [{"t": "text", "b": "Pump gear oil into the fill hole until it runs out (about 2.5 litres), then fit the plug."}, {"t": "text", "b": "Fill the LSD with about 1 litre of Haldex fluid the same way, then refit its heat shield.", "only": ["lsd"]}]}, {"chapter": "fluids", "title": "Button up and break it in", "blocks": [{"t": "text", "b": "Battery tray, battery, intake, engine cover. Wheels on and torqued, belly pan on."}, {"t": "torque", "label": "wheel bolts", "nm": 120, "c": {"level": "high", "n": 2, "note": "FCP Euro clutch DIY and VW MQB spec."}}, {"t": "text", "b": "Drive gently for the first few hundred miles: no launches and no full-throttle shifts while the disc beds in."}, {"t": "note", "b": "Performance clutches usually have their own break-in distance. Follow it.", "only": ["perf"]}]}], "alsoReplace": [{"name": "Rear main seal", "why": "A leak here soaks the new disc. It''s behind the flywheel you just removed."}, {"name": "Shift cable bushings", "why": "Both cables are already disconnected at the gearbox. Five minutes now.", "only": ["ttrs", "perf"]}, {"name": "Dogbone mount insert", "why": "The mount is already unbolted, and a firmer insert pairs well with a stronger clutch."}, {"name": "Clutch delay valve", "why": "Some owners remove the delay valve in the clutch line for a quicker engagement while the line is apart."}], "check": {"tab": "Reading the old parts", "title": "Reading the old parts", "illId": "mk7-clutch-check", "illCap": "Heat spots, rivet depth and dual-mass play.", "rows": [{"see": "Blue-black spots or cracks on the flywheel face", "means": "It''s been slipping hot.", "do": "Replace the flywheel; resurfacing a dual-mass isn''t worth it."}, {"see": "Oil on the disc or in the bell housing", "means": "Rear main seal or input shaft seal is leaking.", "do": "Replace the seal now, or the new disc will be contaminated."}, {"see": "Dual-mass halves clunk or have lots of free play", "means": "The springs inside are worn.", "do": "Replace the flywheel with the clutch."}], "c": {"level": "medium", "n": 2, "note": "FCP Euro and general clutch-inspection practice."}}, "aftercare": ["Check the bite point and that every gear engages cleanly, including reverse.", "Look for leaks at the gearbox and LSD plugs and the clutch line after the first drive.", "Recheck the wheel bolts after 50 miles."], "disagreements": [{"topic": "Reusing the dual-mass flywheel", "pos": "Some reuse a good one to save several hundred dollars; most specialists replace it with the clutch.", "call": "Replace it unless it passes the play test, has no heat damage, and the car is staying stock."}, {"topic": "Single-mass flywheel", "pos": "Fans like the rev response; others hate the rattle and vibration.", "call": "Dual-mass for a daily driver. Single-mass only if you accept the noise."}, {"topic": "Included alignment tool", "pos": "Kits ship a plastic tool; experienced installers say use the proper VW one.", "call": "Use a proper VW-style tool. A disc off-centre can damage the hub springs."}], "sources": ["FCP Euro: How To Replace A Volkswagen Mk7 Clutch (Mk7 GTI & Golf R), with full torque list", "Deutsche Auto Parts: How to install a TT RS clutch on a Mk7", "golfmk7.com: Clutch DIY questions (parts list, rear main seal, gearbox oil volume)", "golfmk6.com: 6-speed clutch replacement DIY (alignment tool, bench-bleeding the slave)"], "embeds": [{"id": "dxZoBldb5Po", "note": "FCP Euro''s full Mk7 GTI clutch replacement."}]}'::jsonb);
insert into guides (id, content) values ('shifter-mk7', '{"title": "Short shifter & shifter bushings", "category": "Drivetrain", "fits": "2015–2021 GTI with 6-speed manual", "alsoFits": "Same 02Q selector on the Mk7 Golf, Golf R and GLI manuals, and the Mk5/Mk6 GTI.", "heroId": "mk7-shift-hero", "heroCap": "The parts you''ll touch, on top of the gearbox.", "variants": {"questions": [{"question": "What are you installing?", "options": [{"id": "lever", "label": "Short shift lever", "when": "Shorter fore-aft throw."}, {"id": "bushings", "label": "Shifter bushings", "when": "Takes the slop out of the cables. No change to throw."}, {"id": "both", "label": "Both", "when": "The full shift-feel upgrade."}]}]}, "glance": {"why": "The cheapest way to make the gearbox feel tighter. It''s all on top of the gearbox: no lifting the car.", "timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$40–300", "risk": "Clips and bushings are easy to lose into the engine bay.", "note": "Short shift kits run about $100–250; bushing sets $30–80."}, "lifespan": {"headline": ["Factory rubber bushings soften with age"], "detail": "Vague gear positions or a lever that wobbles in gear are the signs. Aluminium replacements don''t wear the same way.", "factors": ["High mileage", "Engine heat", "Spirited driving"], "confidence": {"level": "community", "n": 3, "note": "Owner reports on golfmk7.com and VWROC."}}, "should": {"yesIf": ["The lever feels vague or has slop in gear", {"text": "You want shorter, quicker throws", "only": ["lever", "both"]}, {"text": "Shifts feel delayed or rubbery under hard driving", "only": ["bushings", "both"]}], "codes": [], "notes": [{"text": "A short shifter shortens fore-aft travel only. Side-to-side across the gate stays the same.", "only": ["lever", "both"]}, {"text": "Some kits come with a new side-to-side lever. If yours does, you may only need part of a bushing set.", "only": ["both"]}], "confidence": {"level": "medium", "n": 3, "note": "CTS Turbo product notes and owner threads."}}, "parts": [{"tier": "aftermarket", "name": "Short shift kit", "note": "Replaces the primary lever on top of the gearbox. Check it fits the 02Q selector.", "price": "$100–250", "only": ["lever", "both"]}, {"tier": "aftermarket", "name": "Shift cable end-link bushings", "note": "Aluminium with bronze liners in place of the rubber at the cable ends.", "price": "$30–60", "only": ["bushings", "both"]}, {"tier": "aftermarket", "name": "Shift cable bracket bushings", "note": "Optional. Owners disagree on how much difference they make.", "price": "$25–40", "only": ["bushings", "both"]}], "aftermarket": [{"name": "CTS Turbo short shift kit (02M/02Q)", "note": "Billet aluminium with a steel selector insert. 20% or 35% throw reduction; side-to-side unchanged.", "links": [{"store": "CTS Turbo", "url": "https://ctsturbo.com/product/cts-turbo-o2m-o2q-short-shift-kit/"}], "only": ["lever", "both"]}, {"name": "APR short shift kit", "note": "Clear, photo-by-photo installation PDF from APR.", "links": [{"store": "APR instructions", "url": "https://documents.goapr.com/871479ad444c185aae4f95f368e0319662489ac3.pdf"}], "only": ["lever", "both"]}, {"name": "Racingline short shifter", "note": "Comes with a new side-to-side lever, so a full bushing kit is partly redundant.", "only": ["lever", "both"]}, {"name": "Spulen or VWR adjustable shifters", "note": "Adjustable throw. Owners suggest stopping short of the shortest setting.", "only": ["lever", "both"]}, {"name": "42 Draft Designs shifter bushing set", "note": "CNC aluminium bushings with oil-impregnated bronze bearings. The side-to-side end link needs a small modification.", "links": [{"store": "42 Draft Designs", "url": "https://www.42draftdesigns.com/vw-shifter-bushing-set-mk7-6s-my15/"}], "only": ["bushings", "both"]}, {"name": "CTS Turbo shifter end-link bushing set", "note": "Fits Mk5 through Mk8 cable shifters.", "price": "about $32", "only": ["bushings", "both"]}], "tools": [{"name": "Torx T25, 13 mm socket, flat screwdriver", "price": "$15"}, {"name": "Small puller or a socket and hammer", "note": "To break the primary lever off its shaft.", "price": "$20", "only": ["lever", "both"]}, {"name": "Sharp blade and a vise or bench press", "note": "To cut out and press the end-link bushings.", "price": "$20", "only": ["bushings", "both"]}, {"name": "Torque wrench", "price": "$40", "only": ["lever", "both"]}, {"name": "Magnetic tray", "note": "Clips disappear down the back of the engine.", "price": "$10"}], "before": ["Car in neutral with the handbrake on.", "Take photos of the cables and clips before you unhook anything."], "chapters": [{"id": "access", "title": "Get to it"}, {"id": "lever", "title": "Short shift lever"}, {"id": "bush", "title": "Bushings"}, {"id": "finish", "title": "Finish"}], "steps": [{"chapter": "access", "title": "Clear the top of the gearbox", "blocks": [{"t": "ill", "id": "mk7-shift-hero", "cap": "Primary lever, relay lever, cable ends and bracket."}, {"t": "text", "b": "Remove the two T25 screws holding the intake to the radiator support and lift out as much of the intake as you need. If there still isn''t room, take out the battery and its tray."}]}, {"chapter": "access", "title": "Unhook the cable ends", "blocks": [{"t": "text", "b": "Lift the centre tab of each spring clip and slide it off, then slide both cable ends off their posts on the selector."}]}, {"chapter": "lever", "only": ["lever", "both"], "title": "Remove the primary lever", "blocks": [{"t": "text", "b": "With the gearbox in neutral, loosen the nut on the primary lever and back it off one turn. Tap the nut with a socket and hammer, or use a small puller, to break the lever off the splined shaft. Then remove the nut and lift the lever off, wiggling side to side."}, {"t": "warn", "b": "Don''t slam the lever up or down to free it. The selector shaft inside the gearbox takes the hit."}]}, {"chapter": "lever", "only": ["lever", "both"], "title": "Fit the short shift lever", "blocks": [{"t": "ill", "id": "mk7-shift-throw", "cap": "Pick a setting before you tighten it."}, {"t": "text", "b": "Set the cable post in the hole for the throw you want, fit the lever onto the shaft and tighten its nut carefully."}, {"t": "torque", "label": "short shifter nut", "nm": 34, "c": {"level": "single", "n": 1, "note": "CTS Turbo''s instruction (25 lb-ft) for their 02M/02Q kit. Use your own kit''s figure if it differs."}}]}, {"chapter": "bush", "only": ["bushings", "both"], "title": "Replace the end-link bushings", "blocks": [{"t": "text", "b": "Pop the rubber bushing out of the fore-aft cable end. For the side-to-side cable, the whole rubber section has to be cut out with a sharp blade."}, {"t": "text", "b": "Press the new bushings in and secure them with the supplied clips."}, {"t": "text", "b": "To remove the side-to-side relay lever, take off its white clip, pry the linkage forward over its notch, rotate it anticlockwise and slide it out of the metal sleeve."}]}, {"chapter": "bush", "only": ["bushings", "both"], "title": "Replace the bracket bushings", "blocks": [{"t": "text", "b": "Undo the cable bracket''s three 13 mm bolts, swap the rubber bushings under them for the new ones, and refit the bracket."}]}, {"chapter": "finish", "title": "Reconnect and check every gear", "caution": true, "blocks": [{"t": "text", "b": "Slide the cable ends back on and refit the clips. With the engine off and the clutch down, run through every gear including reverse."}, {"t": "text", "b": "If gears on one side of the gate are hard to find after new bushings, re-centre the selector cable following your kit''s instructions. One kit''s instructions left this out, according to owners."}]}, {"chapter": "finish", "title": "Refit and test drive", "blocks": [{"t": "text", "b": "Refit the intake (and battery and tray if removed). On the road, check every gear engages cleanly before you push it."}]}], "alsoReplace": [{"name": "Shifter bushings", "why": "The cables are already off. Doing both at once gives the most noticeable change.", "only": ["lever"]}, {"name": "Short shift lever", "why": "Already at the selector. The lever is a 20-minute add-on.", "only": ["bushings"]}], "check": {"tab": "How it should feel", "title": "How it should feel", "illId": "mk7-shift-throw", "illCap": "Shorter throw, same gate.", "rows": [{"see": "Clean, notchy engagement in every gear", "means": "Everything is connected properly.", "do": "Enjoy it."}, {"see": "One side of the gate is hard to find", "means": "The cable needs re-centring after the bushing change.", "do": "Re-centre it per your kit''s instructions."}, {"see": "More buzz through the lever", "means": "Solid bushings pass on more vibration.", "do": "Normal. Bracket bushings add the most; skip them if you hate it."}], "c": {"level": "community", "n": 3, "note": "Owner reports on golfmk7.com and VWROC."}}, "aftercare": ["Check the clips are still seated after the first week.", {"text": "Recheck the lever nut after a few hundred miles.", "only": ["lever", "both"]}], "disagreements": [{"topic": "Bracket bushings", "pos": "Some owners noticed a real difference; others felt nothing over the end-link bushings and short shifter.", "call": "Do the end links first. Add bracket bushings if you still want more."}, {"topic": "Shortest setting", "pos": "Some go as short as possible; others say the shortest setting gets notchy and heavy.", "call": "Start at the middle or longer setting. You can always go shorter."}], "sources": ["CTS Turbo: 02M/02Q short shift kit (throw reduction, nut torque, fitment)", "APR short shift kit installation instructions (TL100076)", "AutoInstruct: Mk7 short shifter and solid bushing installation", "42 Draft Designs: Mk7 shifter bushing set", "golfmk7.com and VWROC owner threads on bushings, brackets and setup"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('battery-mk7', '{"title": "Battery replacement & adaptation", "category": "Electrical", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Same procedure on every MQB car with a battery monitoring sensor: Golf, Golf R, Jetta, A3.", "heroId": "mk7-batt-hero", "heroCap": "Order matters: negative off first, on last.", "variants": {"questions": [{"question": "What are you fitting?", "options": [{"id": "oe", "label": "Same type and size", "when": "Match the label on your old one: AGM or EFB, same Ah.", "oeOnly": true}, {"id": "upgrade", "label": "A different battery", "when": "Higher capacity, or an Odyssey or Optima AGM."}]}, {"question": "Do you have a VW scan tool?", "hint": "The car has to be told it has a new battery. That needs OBDeleven, VCDS or a shop.", "options": [{"id": "tool", "label": "Yes: OBDeleven or VCDS", "when": "You''ll do the adaptation yourself."}, {"id": "notool", "label": "No", "when": "Fit it now and have the adaptation done soon after."}]}]}, "glance": {"why": "A 20-minute swap, plus one step most people skip: telling the car about it.", "timeFirst": "30–45 min", "timeRepeat": "20 min", "difficulty": 1, "cost": "$180–350", "risk": "Skipping the adaptation shortens the new battery''s life.", "note": "Cost is for an AGM or EFB battery; Odyssey and Optima run higher."}, "lifespan": {"headline": ["Usually 4–6 years"], "detail": "Short trips and lots of electrical load drain it faster. On start-stop cars, a weak battery disables start-stop before it fails to start the car.", "factors": ["Short trips", "Heat", "Car parked for weeks", "Dash cams and other always-on loads"], "inspect": ["Load-test it at 4 years"], "confidence": {"level": "community", "n": 2, "note": "General battery-life range; VW''s tech tip on start-stop shutting off when charge drops."}}, "should": {"yesIf": ["The engine cranks slowly, especially on cold mornings", "Start-stop has stopped working and the battery tests weak", "The battery is over five years old and fails a load test"], "codes": [], "notes": ["Start-stop also shuts off when the battery''s charge reading drops below about 12.1 V. Charge it and test it before you buy a new one.", {"text": "A bigger battery is fine, but the car has to be coded for its type and capacity, or the charging system will treat it as the old one.", "only": ["upgrade"]}], "confidence": {"level": "high", "n": 2, "note": "VW of America tech tips 27-19-01TT and 27-20-02TT (2015–2021, all models with battery monitoring)."}}, "parts": [{"tier": "oe", "name": "Battery, same type as fitted", "note": "Most GTIs take an H6 (group 48) size. VW fitted 61, 68 and 72 Ah versions depending on equipment; copy the type (AGM or EFB) and Ah from your old label.", "price": "$180–260", "only": ["oe"]}, {"tier": "aftermarket", "name": "Replacement battery, your choice", "note": "Same H6 footprint and terminal layout. Pick from the aftermarket list.", "price": "$220–350", "only": ["upgrade"]}, {"name": "Terminal cleaning brush and dielectric grease", "price": "$10"}], "aftermarket": [{"name": "Odyssey Performance 48-720 (H6 AGM)", "note": "Heavy-duty AGM in the factory size. Code the car as AGM."}, {"name": "Optima YellowTop DH6", "note": "Spiral-cell AGM with deep-cycle tolerance, for cars with lots of accessories. Code the car as AGM."}], "tools": [{"name": "10 mm and 13 mm sockets, extension", "price": "$15"}, {"name": "OBDeleven or VCDS", "note": "For the adaptation.", "price": "$60–200", "only": ["tool"]}, {"name": "Memory saver (optional)", "note": "Plugs into the OBD port to keep settings while the battery''s out.", "price": "$20"}, {"name": "Gloves and eye protection", "price": "$10"}], "before": ["Keys out of the car, all doors and the hood closed except the one you''re working at.", "Take a photo of the new battery''s label: part number, manufacturer code, serial number, type and capacity.", "Note your radio presets and seat memory if you care about them."], "chapters": [{"id": "swap", "title": "Swap it"}, {"id": "adapt", "title": "Adapt it"}], "steps": [{"chapter": "swap", "title": "Open up the battery", "blocks": [{"t": "text", "b": "The battery is at the front left of the engine bay under a plastic cover. Lift the cover off."}]}, {"chapter": "swap", "title": "Disconnect negative, then positive", "caution": true, "blocks": [{"t": "ill", "id": "mk7-batt-hero", "cap": "Negative first, sensor stays on its clamp."}, {"t": "text", "b": "Loosen the 10 mm nut on the negative clamp and lift the clamp off the post. The battery monitoring sensor is built onto that clamp: lift both together and never pry the sensor or pull on its wire."}, {"t": "text", "b": "Flip up the red cover and disconnect the positive the same way."}]}, {"chapter": "swap", "title": "Lift the old battery out", "blocks": [{"t": "text", "b": "Remove the 13 mm bolt and clamp at the base of the battery, and unplug the vent tube from the side if fitted. Lift straight up: it''s heavy."}]}, {"chapter": "swap", "title": "Fit the new battery", "blocks": [{"t": "text", "b": "Clean the tray and the terminal clamps. Set the new battery in the same way round, reconnect the vent tube, and refit the base clamp."}, {"t": "text", "b": "Connect the positive first, then the negative with its sensor. Snug the nuts so the clamps can''t turn by hand; they''re small, so don''t crank on them. A thin film of dielectric grease keeps corrosion off."}]}, {"chapter": "swap", "title": "Reset the small things", "blocks": [{"t": "text", "b": "Start the car. Close each window fully and hold the switch up a second longer to re-learn one-touch. Turn the steering lock to lock once if the stability-control light stays on. Set the clock."}]}, {"chapter": "adapt", "only": ["tool"], "title": "Adapt the battery", "caution": true, "blocks": [{"t": "ill", "id": "mk7-batt-label", "cap": "These come off the new battery''s label."}, {"t": "text", "b": "OBDeleven has a one-click battery replacement app. In VCDS, go to 19 Gateway, then Adaptation, and enter the new battery''s part number, manufacturer code and serial number."}, {"t": "text", "b": "Because the battery differs from the original, also set its type (AGM or EFB) and capacity in the same adaptation.", "only": ["upgrade"]}, {"t": "note", "b": "If your battery''s label has no VW-style codes, follow your scan tool''s prompt for generic batteries."}]}, {"chapter": "adapt", "only": ["notool"], "title": "Get it adapted soon", "blocks": [{"t": "text", "b": "The car runs fine without the adaptation, but start-stop won''t work, the charging system keeps managing the battery as if it were the old one, and you may see fault codes. Any VW dealer or independent with a scan tool can do it in a few minutes."}]}], "alsoReplace": [{"name": "Key fob batteries", "why": "A 2-minute job while you have the small screwdriver out."}], "check": {"tab": "Did it take?", "title": "Did it take?", "illId": "mk7-batt-label", "illCap": "Label details go into the gateway adaptation.", "rows": [{"see": "Start-stop works again after a drive or two", "means": "The adaptation took and the battery is charged.", "do": "Nothing more to do."}, {"see": "Start-stop still off, no faults", "means": "The battery is low, or the car is still learning it.", "do": "Drive 30 minutes or charge it, then check again."}, {"see": "Battery or charging fault codes", "means": "Adaptation missing or the wrong type entered.", "do": "Redo the adaptation with the right type and capacity."}], "c": {"level": "high", "n": 2, "note": "VW of America tech tips 27-19-01TT and 27-20-02TT (2015–2021, all models with battery monitoring)."}}, "aftercare": ["Recycle the old battery where you bought the new one; most stores refund a core charge.", "Check the clamps are still tight after a week."], "disagreements": [{"topic": "Is the adaptation really necessary?", "pos": "Plenty of owners never do it and the car starts fine.", "call": "Do it. VW says skipping it can compromise charging and shorten the new battery''s life."}, {"topic": "Memory saver through the OBD port", "pos": "Some swear by them; others say they can blow a fuse if the positive clamp touches metal.", "call": "Optional. If you use one, keep the loose positive clamp wrapped in a rag."}], "sources": ["VW of America tech tip 27-19-01TT: start-stop inoperative, including after battery replacement", "VW of America tech tip 27-20-02TT: battery adaptation, 2015–2021, all models", "VW 2015 Golf / GTI / Golf R maintenance parts list (battery part numbers and capacities)", "FCP Euro Mk7 clutch DIY (battery and tray removal)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('headlight-bulbs-mk7', '{"title": "Headlight bulb replacement", "category": "Electrical", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Mk7 Golf and Golf SportWagen use the same halogen and xenon bulbs.", "heroId": "mk7-bulb-hero", "heroCap": "Low beam, high beam and the two ways in.", "variants": {"questions": [{"question": "Which headlights do you have?", "hint": "Bi-xenon cars have a round projector lens with U-shaped LED running lights around it.", "options": [{"id": "halogen", "label": "Halogen", "when": "Reflector bowl. Base cars."}, {"id": "xenon", "label": "Bi-xenon", "when": "Projector lens. 2015–2017 Lighting Package cars."}, {"id": "led", "label": "Full LED", "when": "2018–2021 upper trims. No bulbs to change."}]}]}, "glance": {"why": "Halogens are a quick swap from the engine bay; xenons come out through the wheel arch, no headlight removal needed.", "timeFirst": "20 min–2.5 hr", "timeRepeat": "15 min–1 hr", "difficulty": 2, "cost": "$15–200", "risk": "Xenon bulbs run at high voltage. Lights off and key out.", "note": "Halogen is the quick end of the range; a pair of xenon bulbs takes a couple of hours the first time."}, "lifespan": {"headline": [{"text": "Halogens: a few years", "only": ["halogen"]}, {"text": "Xenons: far longer than halogens", "only": ["xenon"]}, {"text": "LEDs: life of the car, usually", "only": ["led"]}], "detail": "Replace bulbs in pairs. The surviving one is close behind, and a new and an old bulb won''t match in colour.", "factors": ["Daytime running lights on high beam bulbs", "Vibration", "Touching the glass"], "confidence": {"level": "community", "n": 2, "note": "General bulb-life experience from owners; varies widely."}}, "should": {"yesIf": ["A bulb is out and the dash shows a lighting warning", {"text": "A xenon has gone pink or flickers at start-up: it''s on its way out", "only": ["xenon"]}, {"text": "The light output has yellowed or dimmed next to a new car''s", "only": ["halogen", "xenon"]}], "codes": [], "notes": [{"text": "Full LED headlights have no replaceable bulbs. A failed LED module means a new headlight unit; that''s in Exterior.", "only": ["led"]}, {"text": "Plug-in LED or HID bulbs in halogen reflectors scatter light and aren''t DOT-compliant. Brighter street-legal halogens are the safe upgrade.", "only": ["halogen"]}], "confidence": {"level": "medium", "n": 3, "note": "Go-Parts headlight guide, golfmk7.com and vwvortex owner DIYs."}}, "parts": [{"tier": "oem", "name": "H7 low-beam bulbs (pair)", "note": "Philips, Osram or Hella.", "price": "$15–40", "only": ["halogen"]}, {"tier": "oem", "name": "High-beam / DRL bulbs (pair)", "note": "2015–2017 halogen cars use H15. On 2018+ halogen cars, check the bulb you remove; retailers list H11.", "price": "$20–45", "only": ["halogen"]}, {"tier": "oem", "name": "D3S xenon bulbs (pair)", "note": "Philips or Osram, 35 W. Stock colour is about 4300K.", "price": "$120–200", "only": ["xenon"]}], "aftermarket": [{"name": "Philips X-tremeVision or Osram Night Breaker H7", "note": "Street-legal halogens with more throw. They wear out faster than standard bulbs.", "only": ["halogen"]}, {"name": "Higher-Kelvin D3S bulbs (5000–6000K)", "note": "Whiter light. Above about 6000K, usable light on the road drops off.", "only": ["xenon"]}], "tools": [{"name": "Nitrile gloves", "note": "Skin oil on the glass shortens bulb life.", "price": "$5"}, {"name": "T20 and T25 Torx bits", "note": "Wheel-arch liner screws. A second T20 on a socket screwdriver helps with the hard-to-reach one.", "price": "$10", "only": ["halogen", "xenon"]}, {"name": "Flat screwdriver and a rubber jar-opener pad", "note": "Grip for stubborn caps.", "price": "$5", "only": ["halogen", "xenon"]}, {"name": "Alcohol wipes", "note": "To clean the new bulb''s glass if you touch it.", "price": "$3", "only": ["halogen", "xenon"]}, {"name": "Scan tool (optional)", "note": "Clears a lingering bulb warning in 09 Central Electrics.", "price": "$60"}], "before": ["Lights off, key out, and let a recently used bulb cool.", {"text": "Turn the steering to full lock away from the side you''re working on to open up the wheel arch.", "only": ["halogen", "xenon"]}], "chapters": [{"id": "low", "title": "Low beam"}, {"id": "high", "title": "High beam / DRL"}, {"id": "xen", "title": "Bi-xenon bulb"}, {"id": "led", "title": "LED headlights"}, {"id": "finish", "title": "Finish"}], "steps": [{"chapter": "low", "only": ["halogen"], "title": "Get to the low-beam cap", "blocks": [{"t": "ill", "id": "mk7-bulb-hero", "cap": "From above, or through the wheel arch."}, {"t": "text", "b": "From the engine bay: on the driver''s side remove the fuse box cover and the high-beam cover for room; the passenger side has more space. If your hands don''t fit, go through the wheel arch instead: remove the few Torx screws joining the front of the liner, and reach in at about 45° to the round cap on the back of the headlight."}]}, {"chapter": "low", "only": ["halogen"], "title": "Swap the H7", "blocks": [{"t": "text", "b": "Twist the cap off. Turn the bulb holder anticlockwise a quarter turn, pull it out, unplug and swap the bulb wearing gloves. Line up the tab, push it in and turn it clockwise until it clicks."}, {"t": "warn", "b": "Go easy on the holder. Its tabs bend, and a bent one means taking the headlight out to fix it."}]}, {"chapter": "high", "only": ["halogen"], "title": "Swap the high-beam / DRL bulb", "blocks": [{"t": "text", "b": "The high-beam cap is the smaller one, reachable from the engine bay. Same quarter-turn holder: out, swap, back in."}]}, {"chapter": "xen", "only": ["xenon"], "title": "Open the wheel-arch liner", "timeSink": true, "blocks": [{"t": "ill", "id": "mk7-bulb-hero", "cap": "Xenons come out through the wheel arch."}, {"t": "text", "b": "With the steering at full lock, remove the T20 screws holding the front section of the liner so you can fold it back. The passenger side has one screw that needs a second T20 on a socket screwdriver."}]}, {"chapter": "xen", "only": ["xenon"], "title": "Swap the D3S bulb", "caution": true, "blocks": [{"t": "text", "b": "Reach in to the large cap on the back of the headlight and twist it off. Unplug the bulb''s connector, release its retaining ring and pull the bulb straight out."}, {"t": "text", "b": "Fit the new bulb without touching the glass (wipe it with alcohol if you do), lock the ring, plug in and refit the cap firmly so no moisture gets in."}, {"t": "warn", "b": "Xenon bulbs start at very high voltage. Never power the light with the bulb out, or touch the connector with the lights on."}, {"t": "note", "b": "Do both sides. A new bulb next to an old one is a visibly different colour."}]}, {"chapter": "led", "only": ["led"], "title": "There''s nothing to replace here", "blocks": [{"t": "text", "b": "Full LED headlights have no serviceable bulbs. If one section is out, check for a lighting fault code in 09 Central Electrics first; if the LED module itself has failed, the fix is a new headlight unit."}]}, {"chapter": "finish", "title": "Test every function", "blocks": [{"t": "text", "b": "Check low beam, high beam, flash-to-pass and the running lights on both sides. If a warning stays on, cycle the ignition, or clear it in 09 Central Electrics."}, {"t": "text", "b": "Refit the wheel-arch liner screws.", "only": ["halogen", "xenon"]}]}, {"chapter": "finish", "title": "Check the aim", "blocks": [{"t": "text", "b": "Park on level ground facing a wall at night. Both low-beam cut-offs should sit at the same height, slightly below the headlight centres. If one is off, it may not be fully seated."}]}], "alsoReplace": [{"name": "The other side''s bulb", "why": "Bulbs fail in pairs a few months apart, and colour matters.", "only": ["halogen", "xenon"]}], "check": {"tab": "Which lights?", "title": "Which headlights do you have?", "illId": "mk7-bulb-id", "illCap": "Halogen reflector, bi-xenon projector, or full LED.", "rows": [{"see": "Plain reflector bowl behind clear glass", "means": "Halogen.", "do": "H7 low beam, plus the high-beam / DRL bulb."}, {"see": "Round projector lens with U-shaped LED running lights", "means": "Bi-xenon, 2015–2017 Lighting Package.", "do": "D3S bulbs through the wheel arch."}, {"see": "LED strips and a small projector, no bulb caps", "means": "Full LED, 2018–2021.", "do": "No bulbs; a failed module means a new unit."}], "c": {"level": "medium", "n": 2, "note": "Go-Parts Mk6/Mk7 headlight guide and retailer bulb charts."}}, "aftercare": ["Recheck for warnings on the next couple of drives.", {"text": "Look for condensation inside the lens after rain; a loose cap lets moisture in.", "only": ["halogen", "xenon"]}], "disagreements": [{"topic": "Engine bay or wheel arch for halogen lows", "pos": "Some owners manage from above with the covers off; others say the wheel arch is the only comfortable way.", "call": "Try from above first. Go through the arch if your hands don''t fit."}, {"topic": "Removing the bumper for xenons", "pos": "One widely shared guide removes the grille and headlights.", "call": "Not needed. The wheel-arch route takes 2–3 hours for both sides with nothing major removed."}], "sources": ["vwvortex: DIY Bi-Xenon bulb replacement without removing headlights (Mk7 GTI)", "golfmk7.com: halogen headlight bulb replacement thread", "Go-Parts: 2010–2017 VW GTI headlight guide (halogen vs xenon, D3S, H7)", "Xenons Online and Boslla bulb charts (H7, H15, D3S; 2018+ high beam)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('front-bumper-mk7', '{"title": "Front bumper cover removal", "category": "Exterior", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Same layout on the Mk7 Golf. Needed for headlights, intercoolers, radiators and bumper repairs.", "heroId": "mk7-bumper-hero", "heroCap": "Grille, wheel arches and underside. Almost every screw is T25.", "glance": {"why": "The gateway to half the jobs at the front of the car. Once you''ve done it, it''s a 30-minute job.", "timeFirst": "1–1.5 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$0–15", "risk": "Forgetting the fog-light plugs and tearing the wiring.", "note": "Cost is a few spare clips and screws; old ones go missing."}, "should": {"yesIf": ["You''re replacing a headlight unit", "You''re fitting an intercooler or replacing a radiator", "A bumper bracket or the lower grille is broken"], "codes": [], "notes": ["For a headlight alone you can often just drop the bumper a few inches instead of taking it off."], "confidence": {"level": "medium", "n": 4, "note": "vwvortex and golfmk6 owner DIYs, ARM Motorsports'' MQB intercooler guide and ECS''s Mk7 headlight instructions. Screw counts vary slightly by year and by how many went missing before you."}}, "parts": [{"tier": "oe", "name": "Spare T25 bumper screws and push-rivets", "note": "Several always break or go missing.", "price": "$10–15"}], "tools": [{"name": "T25 Torx on a ratchet, with 2–4\" extension", "price": "$10"}, {"name": "T25 L-key", "note": "Fits under the car where a ratchet won''t.", "price": "$3"}, {"name": "T30 Torx", "note": "A couple of cars have T30s at the bumper ends.", "price": "$3"}, {"name": "Trim pick", "note": "Push-rivets on the lower liners.", "price": "$5"}, {"name": "Moving blanket or cardboard", "note": "Somewhere soft to set the bumper down.", "price": "$0"}], "before": ["Turn the steering to full lock to open each wheel arch, or take the front wheels off for the best access.", "Have a tray or labelled bags ready: screw lengths differ between locations."], "steps": [{"title": "Remove the upper grille", "blocks": [{"t": "ill", "id": "mk7-bumper-hero", "cap": "Upper grille first, then the arches and underside."}, {"t": "text", "b": "Undo the two T25 screws along the top edge of the grille. Pull the top of the grille slightly toward you and lift it up: four clips hold it."}, {"t": "text", "b": "Behind it, remove the two T25 screws holding the bumper to the upper cross-member, if your car has them."}]}, {"title": "Wheel-arch screws", "timeSink": true, "blocks": [{"t": "text", "b": "In each wheel arch remove the T25 screws joining the liner to the bumper (about five). Pull the liner back to find the one vertical screw at the top that holds the bumper corner to the fender: an extension helps."}, {"t": "text", "b": "Pop out the push-rivet on the lower liner with a pick."}]}, {"title": "Underside screws", "blocks": [{"t": "text", "b": "Under the car, remove the two T25 screws per side that hold the liners to the bumper, and the screws along the bumper''s lower edge. Take the belly pan off too if you''re doing anything behind the bumper."}]}, {"title": "Release the sides", "caution": true, "blocks": [{"t": "text", "b": "At each front wheel, pull the bumper corner outward to release it from its guide on the fender. Dirt in the guide makes it sound like it''s cracking; it usually isn''t. Work from one side to the other."}]}, {"title": "Unplug and lift it away", "caution": true, "blocks": [{"t": "text", "b": "Pull the bumper forward a few inches and support it. Unplug both fog lights and, on cars with headlight washers, the washer hose. Then lift it clear and set it on something soft."}, {"t": "warn", "b": "Don''t let it hang on the fog-light wiring."}]}, {"title": "Refitting", "blocks": [{"t": "text", "b": "Line up both sides in their fender guides and press them home, then plug in the fogs. Start every screw by hand before tightening any, so the bumper can find its position."}]}], "alsoReplace": [{"name": "Broken bumper clips and brackets", "why": "Cheap, and a rattle-free bumper is a nice side effect."}], "check": {"tab": "Lined up?", "title": "Is it lined up?", "illId": "mk7-bumper-hero", "illCap": "Every location gets its screws back.", "rows": [{"see": "Even gap to the fender and headlight on both sides", "means": "Both side guides are seated.", "do": "Done."}, {"see": "One corner stands proud of the fender", "means": "That side missed its guide.", "do": "Pull it out and re-seat it before fitting the arch screws."}, {"see": "Fog light not working", "means": "Connector not fully clicked in.", "do": "Reach behind the bumper and push it home."}], "c": {"level": "medium", "n": 4, "note": "vwvortex and golfmk6 owner DIYs, ARM Motorsports'' MQB intercooler guide and ECS''s Mk7 headlight instructions. Screw counts vary slightly by year and by how many went missing before you."}}, "aftercare": ["Check the bumper after the first car wash: a loose corner flutters at speed."], "disagreements": [{"topic": "How many wheel-arch screws", "pos": "Guides say four, five, or five plus two long ones.", "call": "It varies by year and history. Keep going until the liner flexes freely away from the bumper."}, {"topic": "Full removal or drop it", "pos": "Some guides remove the bumper for headlight work; others only drop it.", "call": "Drop it for a headlight; remove it for anything behind it."}], "sources": ["vwvortex: GTI Mk7 front bumper removal thread", "ARM Motorsports: Mk7 Jetta GLI front-mount intercooler guide (MQB bumper fasteners)", "ECS Tuning: Mk7 Golf Helix headlights installation (bumper removal steps)", "blog.rayalner.com: removing the driver-side headlight on a 2016 GTI"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('headlight-unit-mk7', '{"title": "Headlight unit replacement", "category": "Exterior", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Mk7 Golf headlights share the mounting; Mk7.5 units need coding and wiring adapters on a Mk7.", "heroId": "mk7-headlight-screws", "heroCap": "Three screws hold each headlight.", "variants": {"questions": [{"question": "What''s going in?", "options": [{"id": "same", "label": "The same type of headlight", "when": "Cracked lens, failed LED module, condensation.", "oeOnly": true}, {"id": "upgrade", "label": "A different headlight", "when": "Mk7.5 LED units on a Mk7, or an aftermarket design."}]}, {"question": "What does your car have now?", "options": [{"id": "halogen", "label": "Halogen", "when": "Reflector bowl, no projector."}, {"id": "hid", "label": "Bi-xenon or LED", "when": "Projector lens; self-levelling."}]}]}, "glance": {"why": "Two screws from above, one behind the bumper. The bumper is the real work.", "timeFirst": "1.5–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$250–1,500", "risk": "Projector headlights need their aim reset with a scan tool.", "note": "Price depends on type: halogen units are the low end, new OE LED units the high end. Used OEM units are common."}, "should": {"yesIf": ["The lens is cracked, or the inside stays fogged after the caps are resealed", "One section of an LED headlight has failed", {"text": "You want the Mk7.5 LED look on a 2015–2017 car", "only": ["upgrade"]}], "codes": [], "notes": ["Check the caps on the back first: a loose bulb cap is the usual cause of condensation, and it''s free to fix.", {"text": "Mk7.5 LED units on a Mk7 need wiring adapters and coding. Buy a kit that includes both, and its instructions.", "only": ["upgrade"]}], "confidence": {"level": "medium", "n": 3, "note": "Owner DIYs and ECS''s headlight installation guide."}}, "parts": [{"tier": "oem", "name": "Headlight unit (side to suit)", "note": "Match type exactly: halogen, bi-xenon or LED, and with or without adaptive lighting.", "price": "$250–1,200", "only": ["same"]}, {"tier": "aftermarket", "name": "Upgrade headlight kit (pair)", "note": "Should include any wiring adapters and coding instructions.", "price": "$600–1,500", "only": ["upgrade"]}, {"tier": "oe", "name": "Spare bumper screws and clips", "price": "$10"}], "aftermarket": [{"name": "ECS Helix Mk7.5-style headlights", "note": "Mk7.5 look for Mk7 cars; ECS''s instructions cover bumper removal and fitting.", "only": ["upgrade"], "links": [{"store": "ECS install PDF", "url": "http://bd8ba3c866c8cbc330ab-7b26c6f3e01bf511d4da3315c66902d6.r6.cf1.rackcdn.com/PDF_27537_Volkswagen_MK7_Golf_Helix_Mk7.5_Style_Headlights_Installation.pdf"}]}, {"name": "Genuine Mk7.5 LED retrofit", "note": "OEM units with an adapter harness. Needs coding in the central electrics and headlight modules.", "only": ["upgrade"]}], "tools": [{"name": "T25 Torx bits, right-angle driver", "note": "One headlight screw can need a T27 if the head is worn.", "price": "$15"}, {"name": "Scan tool (OBDeleven or VCDS)", "note": "Headlight aim basic setting; coding for upgrades.", "price": "$60–200", "only": ["hid", "upgrade"]}, {"name": "Masking tape", "note": "Protects the fender paint as the unit comes out.", "price": "$5"}], "before": ["Turn the lights off and take the key out.", "Tape the fender edge and bumper next to the headlight."], "steps": [{"title": "Remove the grille and drop the bumper", "blocks": [{"t": "text", "b": "Remove the upper grille (two T25 screws, pull forward and up). Then remove the wheel-arch screws and the underside screws on that side so the bumper corner can drop a few inches. The Front bumper cover removal guide has the full map."}, {"t": "note", "b": "Changing both headlights, or the bumper fights you? Take it off completely."}]}, {"title": "Undo the three screws", "blocks": [{"t": "ill", "id": "mk7-headlight-screws", "cap": "Two from above, one behind the bumper."}, {"t": "text", "b": "Remove the T25 screw at the front-top of the headlight. Loosen the one at the back: it''s captive and stays with the unit. With the bumper dropped, reach the lower screw and remove it, holding it so it doesn''t fall in."}]}, {"title": "Lift it out and unplug it", "caution": true, "blocks": [{"t": "text", "b": "Lift the headlight up and forward, turning it to clear the bumper bar and radiator support. Unplug the connector on the back and set the unit on a towel."}]}, {"title": "Fit the new unit", "blocks": [{"t": "text", "b": "Plug it in first, then lower it into place. Start all three screws by hand, then snug them. Test every light function before the bumper goes back up."}, {"t": "text", "b": "Follow your kit''s instructions for the adapter harness, and do the coding before you button everything up.", "only": ["upgrade"]}]}, {"title": "Refit the bumper and grille", "blocks": [{"t": "text", "b": "Push the bumper corner back into its fender guide and refit the screws, then the grille."}]}, {"title": "Aim the headlights", "caution": true, "blocks": [{"t": "text", "b": "Projector headlights level themselves: run the headlight range basic setting with your scan tool so the module learns the new unit''s zero point.", "only": ["hid"]}, {"t": "text", "b": "Park on level ground facing a wall and check the low-beam cut-offs are level and slightly below the headlight centres. Adjust with the screws on the back of the unit.", "only": ["halogen"]}]}], "alsoReplace": [{"name": "The other headlight", "why": "If the replacement is new and the other side is yellowed, the difference shows.", "only": ["same"]}], "check": {"tab": "Is it right?", "title": "Is it right?", "illId": "mk7-headlight-screws", "illCap": "All three screws back in.", "rows": [{"see": "Even gaps to bumper and fender", "means": "All three screws are in and the bumper is seated.", "do": "Done."}, {"see": "Headlight warning on the dash", "means": "Plug not fully seated, or an upgrade not coded.", "do": "Reseat the connector; check coding for upgrades."}, {"see": "Cut-off too high or uneven", "means": "Aim not set.", "do": "Run the basic setting (projectors) or adjust the screws (halogen)."}], "c": {"level": "medium", "n": 2, "note": "Owner DIYs."}}, "aftercare": ["Check for condensation after the first rain.", "Recheck the aim at night after a few days."], "disagreements": [{"topic": "Drop or remove the bumper", "pos": "Some remove it fully; others drop one corner and get it done in 20 minutes.", "call": "Drop it for one side. Remove it for two, or if you''re not sure."}], "sources": ["blog.rayalner.com: removing the driver-side headlight on a 2016 GTI with HID", "vwvortex: Mk7 GTI bi-xenon bulb and headlight removal discussion", "ECS Tuning: Mk7 Golf Helix Mk7.5-style headlights installation"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('mirror-glass-mk7', '{"title": "Side mirror glass replacement", "category": "Exterior", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Same glass on the Mk7 Golf, Golf R, SportWagen, Alltrack and 2019–2021 Jetta.", "heroId": "mk7-mirror-glass", "heroCap": "Tilt, pry at the centre, unplug, click the new one on.", "variants": {"questions": [{"question": "What are you fitting?", "options": [{"id": "same", "label": "Replacement glass", "when": "Cracked or missing glass.", "oeOnly": true}, {"id": "euro", "label": "European blind-spot glass", "when": "Aspherical outer edge for a wider view."}]}]}, "glance": {"why": "Clip-on glass with a heater on the back. Ten minutes with no tools beyond a pry stick.", "timeFirst": "20–30 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$25–90", "risk": "Prying at the edge instead of the centre cracks the glass.", "note": "Match heated and, on cars that have it, auto-dimming glass."}, "should": {"yesIf": ["The glass is cracked or fell out", "The heater no longer clears the glass", {"text": "You want less blind spot on the driver''s side", "only": ["euro"]}], "codes": [], "notes": ["Auto-dimming glass is different from standard heated glass. Check before ordering."], "confidence": {"level": "community", "n": 2, "note": "Owner videos and retailer fitment listings."}}, "parts": [{"tier": "aftermarket", "name": "Heated mirror glass with backing plate", "note": "Driver''s side OE part 5G0 857 521 is listed as the reference; check side and auto-dim.", "price": "$25–60", "only": ["same"]}, {"tier": "aftermarket", "name": "European blind-spot (aspherical) glass", "note": "Heated, with backing plate.", "price": "$50–90", "only": ["euro"]}], "tools": [{"name": "Plastic pry tool", "price": "$5"}, {"name": "Thin flat screwdriver, wrapped in tape", "note": "Eases the outer clips.", "price": "$0"}, {"name": "Towel or mat", "note": "Under the mirror in case the glass drops.", "price": "$0"}], "before": ["Warm the glass if it''s cold: cold glass cracks easily.", "Put a towel on the ground under the mirror."], "steps": [{"title": "Tilt the glass and pry it off", "caution": true, "blocks": [{"t": "ill", "id": "mk7-mirror-glass", "cap": "Tilt the top in, pry at the lower centre."}, {"t": "text", "b": "Push the top of the glass inward so the bottom tilts out. Slide the plastic pry tool behind the lower edge toward the centre and pry gently there, where the clips are. A thin screwdriver can ease the outer clips at the same time."}]}, {"title": "Unplug the heater", "blocks": [{"t": "text", "b": "Hold the glass and pull the two heater connectors off the tabs on the back."}]}, {"title": "Click the new glass on", "blocks": [{"t": "text", "b": "Plug the heater wires onto the new glass, line it up with the motor mount, and press firmly with your palm at the centre until it clicks."}]}, {"title": "Test it", "blocks": [{"t": "text", "b": "Adjust the mirror in all four directions with the switch and turn on the rear defrost to check the heater warms the glass."}]}], "alsoReplace": [{"name": "The other side", "why": "Blind-spot glass on one side and flat on the other looks and feels odd.", "only": ["euro"]}], "check": {"tab": "Is it seated?", "title": "Is it seated?", "illId": "mk7-mirror-glass", "illCap": "Firm click at the centre.", "rows": [{"see": "Glass moves with the switch in all directions", "means": "It''s clipped to the motor mount.", "do": "Done."}, {"see": "Glass wobbles or buzzes at speed", "means": "Not fully clicked on.", "do": "Press again at the centre."}, {"see": "Glass stays fogged with the heater on", "means": "Heater wire not on its tab.", "do": "Pop it off and reconnect."}], "c": {"level": "community", "n": 2, "note": "Owner videos."}}, "aftercare": ["Check the glass is still tight after the first car wash."], "disagreements": [{"topic": "Where to pry", "pos": "Some pry at the edge; experienced owners pry behind the centre.", "call": "Centre. The clips are there, and the edge is where it cracks."}], "sources": ["YouTube: Mk7 European blind-spot mirror glass DIY, with owner comments on prying", "YouTube: VW Golf Mk7 mirror glass replacement short", "Retailer fitment listings for Mk7 heated mirror glass (5G0 857 521)"], "embeds": [{"id": "gWD1j4gEka0", "note": "Removing and fitting Mk7 mirror glass."}]}'::jsonb);
insert into guides (id, content) values ('cabin-filter-mk7', '{"title": "Cabin air filter", "category": "Interior", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Same housing across the Mk7 Golf family; the filter part depends on the car''s climate system.", "heroId": "mk7-cabin-filter", "heroCap": "Up under the glovebox in the passenger footwell.", "variants": {"questions": [{"question": "Which filter are you fitting?", "options": [{"id": "std", "label": "Standard pollen filter", "when": "Same as the factory filter.", "oeOnly": true}, {"id": "carbon", "label": "Activated-carbon filter", "when": "Also takes out traffic fumes and smells."}]}]}, "glance": {"why": "A ten-minute job that dealers charge an hour for, and the fix for weak airflow and a musty smell.", "timeFirst": "15–20 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$15–40", "risk": "Fitting it backwards: follow the airflow arrow.", "note": "Lying on your back in the footwell is the hard part."}, "lifespan": {"headline": ["Replaced at the 20,000-mile services"], "detail": "VW''s maintenance schedule changes it every 20,000 miles. Dusty roads, pollen season and city traffic clog it faster.", "factors": ["Dirt roads", "Pollen", "Parking under trees", "Heavy traffic"], "inspect": ["Look at it every oil change"], "confidence": {"level": "high", "n": 1, "note": "VW of America 2015 Golf / GTI / Golf R maintenance parts list."}}, "should": {"yesIf": ["Airflow is weak even on high", "There''s a musty or damp smell from the vents", "The windows fog up and take a long time to clear", "It''s been 20,000 miles or two years"], "codes": [], "notes": ["VW lists two filter part numbers depending on the car''s climate equipment. Match the old filter''s size or the part number printed on it."], "confidence": {"level": "high", "n": 1, "note": "VW of America 2015 maintenance parts list."}}, "parts": [{"tier": "oe", "name": "Cabin (pollen) filter", "pn": "5Q0 819 653 or 5Q0 819 644 A", "note": "Which one depends on equipment. Copy the number on your old filter.", "price": "$15–30", "only": ["std"]}, {"tier": "oem", "name": "Activated-carbon cabin filter", "note": "Same size as your factory filter. Mann, Bosch or Mahle.", "price": "$25–40", "only": ["carbon"]}], "tools": [{"name": "Flashlight", "price": "$0"}, {"name": "Small flat screwdriver or trim tool", "note": "For the cover clips.", "price": "$5"}], "before": ["Ignition off. The blower fan sits right behind the filter.", "Slide the passenger seat all the way back."], "steps": [{"title": "Find the cover", "blocks": [{"t": "ill", "id": "mk7-cabin-filter", "cap": "Under the glovebox, above the passenger footwell."}, {"t": "text", "b": "Lie on your back in the passenger footwell and look up under the glovebox. The filter sits behind a rectangular plastic cover held by clips."}]}, {"title": "Remove the old filter", "blocks": [{"t": "text", "b": "Release the cover''s clips and take it off. Note which way the airflow arrow on the old filter points, then slide the filter down and out. Some debris will fall; that''s normal."}]}, {"title": "Fit the new filter", "blocks": [{"t": "text", "b": "Slide the new filter in with its arrow pointing the same way as the old one. Make sure it sits fully up in the housing and the edges aren''t folded."}, {"t": "text", "b": "Refit the cover until every clip clicks. A loose cover lets air bypass the filter."}]}, {"title": "Check the airflow", "blocks": [{"t": "text", "b": "Run the fan on high with fresh air (not recirculate) and feel the vents."}]}], "alsoReplace": [{"name": "Engine air filter", "why": "On the same 20,000-mile schedule, and a five-minute job under the hood."}], "check": {"tab": "How did it look?", "title": "How did the old one look?", "illId": "mk7-cabin-filter", "illCap": "Arrow direction matters.", "rows": [{"see": "Grey and dusty", "means": "Normal wear.", "do": "You''re on a sensible interval."}, {"see": "Black, with leaves or pine needles", "means": "Overdue, or the car parks under trees.", "do": "Check it more often; clear the cowl drains under the wipers."}, {"see": "Damp or smelling musty", "means": "Water getting in, or a blocked drain.", "do": "Check the cowl and AC drain before the new filter gets the same."}], "c": {"level": "community", "n": 2, "note": "Owner reports."}}, "aftercare": ["Write the date on the new filter''s edge with a marker."], "disagreements": [{"topic": "Carbon or standard", "pos": "Carbon filters cut smells and fumes; some owners find they restrict airflow slightly.", "call": "Carbon if you drive in traffic a lot; standard otherwise."}], "sources": ["VW of America: 2015 Golf / GTI / Golf R & SportWagen maintenance parts list (pollen filter part numbers, 20k interval)", "Owner guides on the Golf 7 filter location behind the glovebox"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('door-panel-mk7', '{"title": "Front door panel removal & speaker upgrade", "category": "Interior", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Mk7 Golf and SportWagen front doors are the same. The Mk7 Jetta has two locking posts under its door pocket.", "heroId": "mk7-door-panel", "heroCap": "Two T30s, one locking post, six clips.", "variants": {"questions": [{"question": "Why are you taking the panel off?", "options": [{"id": "access", "label": "Access only", "when": "Window regulator, lock, check strap, rattles.", "oeOnly": true}, {"id": "speaker", "label": "Upgrading the door speaker", "when": "The factory woofer is riveted in."}]}]}, "glance": {"why": "The way into the door for regulators, locks, check straps and speakers.", "timeFirst": "30–45 min", "timeRepeat": "15 min", "difficulty": 2, "cost": "$5–250", "risk": "Broken panel clips. Buy spares before you start.", "note": "Low end is a bag of clips; the high end is a pair of speakers with adapters."}, "should": {"yesIf": ["A window is slow, noisy or dropped", "The door lock or handle has stopped working properly", "Something rattles inside the door", {"text": "You want better sound from the front doors", "only": ["speaker"]}], "codes": [], "notes": [{"text": "The factory door speakers only handle low frequencies. Pick replacement woofers, and treat tweeters in the pillars as a separate job.", "only": ["speaker"]}], "confidence": {"level": "high", "n": 2, "note": "Crutchfield''s 2015–2021 Golf / GTI install notes and golfmk7.com."}}, "parts": [{"tier": "oe", "name": "Door panel clips", "pn": "7L6 868 243", "note": "Two or three usually break. Buy a bag of ten.", "price": "$5–10"}, {"tier": "aftermarket", "name": "Door woofers (pair)", "note": "Size to fit the factory opening, with the vehicle-specific adapter bracket and harness.", "price": "$100–250", "only": ["speaker"]}, {"name": "Rivets or screws for the new speaker", "note": "The factory speaker is riveted; many owners use screws when refitting.", "price": "$5", "only": ["speaker"]}], "aftermarket": [{"name": "Crutchfield vehicle-fit speakers", "note": "Lists what fits the 2015–2021 Golf and GTI doors, with brackets and harnesses.", "only": ["speaker"], "links": [{"store": "Crutchfield", "url": "https://www.crutchfield.com/learn/2015-2021-vw-golf-and-gti.html"}]}], "tools": [{"name": "Plastic trim tools", "price": "$10"}, {"name": "T30 Torx driver", "note": "A long driver reaches better than a socket.", "price": "$5"}, {"name": "10 mm open-end wrench", "note": "For the quarter-turn locking post.", "price": "$5"}, {"name": "Drill with a 3/16\" bit", "note": "Drills out the factory speaker rivets.", "price": "$0", "only": ["speaker"]}, {"name": "Small magnet", "note": "Fishes the T30s out of their holes.", "price": "$3"}], "before": ["Lower the window a little so the panel lifts off the sill easily.", "Have a box or a helper to hold the panel while you unplug it."], "steps": [{"title": "Remove the two T30 screws", "blocks": [{"t": "ill", "id": "mk7-door-panel", "cap": "Pull cover, armrest, pocket, then the clips."}, {"t": "text", "b": "Pry the outer cover off the door pull with a trim tool to expose a T30 screw, and remove it. Reach under the armrest for the second T30."}]}, {"title": "Release the locking post", "blocks": [{"t": "text", "b": "Inside the door pocket, turn the locking post a quarter turn with the 10 mm wrench to release it."}]}, {"title": "Pop the clips", "caution": true, "blocks": [{"t": "text", "b": "Starting at a bottom corner, slide a trim tool between the panel and the door and pop the six clips along the bottom and sides. Pry close to each clip, not between them."}, {"t": "note", "b": "Any clip that stays in the door: pull it out and push it back into the panel."}]}, {"title": "Lift it off and unplug", "blocks": [{"t": "text", "b": "Lift the panel straight up off the window sill. Support it, unhook the door release cable from the handle, and unplug the switch and light connectors."}]}, {"only": ["speaker"], "title": "Swap the speaker", "blocks": [{"t": "text", "b": "Drill out the four 3/16\" rivets holding the factory speaker, unplug it and lift it out."}, {"t": "text", "b": "Fit the adapter bracket and the new speaker, plug in the harness adapter, and screw or rivet it in place. Test it before the panel goes back on."}]}, {"title": "Refit the panel", "blocks": [{"t": "text", "b": "Hook the release cable back on and plug in every connector. Hang the panel on the window sill, line the clips up with their holes and press each one home with the heel of your hand."}, {"t": "text", "b": "Lock the post, refit both T30s and the pull cover. Check the window, mirror, lock and handle all work."}]}], "alsoReplace": [{"name": "Door check strap", "why": "If the door doesn''t hold open firmly. It comes out through the speaker hole.", "only": ["speaker"]}], "check": {"tab": "All working?", "title": "All working?", "illId": "mk7-door-panel", "illCap": "Every fastener back in.", "rows": [{"see": "Panel flush all round, no rattles", "means": "All clips seated.", "do": "Done."}, {"see": "Gap or rattle along the bottom", "means": "A broken or unseated clip.", "do": "Pop that corner and replace the clip."}, {"see": "Inside handle doesn''t open the door", "means": "Release cable not hooked on.", "do": "Lift the panel and reconnect it."}], "c": {"level": "community", "n": 2, "note": "Owner reports."}}, "aftercare": [{"text": "Listen at volume for buzzing: a loose bracket screw is the usual cause.", "only": ["speaker"]}], "disagreements": [{"topic": "Rivets or screws for the speaker", "pos": "Factory uses rivets; many owners use screws so the speaker can come out again.", "call": "Screws with a little threadlock. Easier next time."}], "sources": ["Crutchfield: upgrading the stereo in a 2015–2021 VW Golf and GTI (door panel and speaker removal)", "golfmk7.com: door check strap DIY (panel clip part number, speaker rivets)", "vwvortex: Mk7 door panel removal thread (clip breakage, Jetta differences)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('turbo-mk7', '{"title": "Turbo upgrade (IS38 and hybrids)", "category": "Forced induction", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T, stock IHI IS20 turbo)", "alsoFits": "Same swap on the Mk7 Golf, GLI and 8V A3 with the IS20. The Golf R and S3 already have the IS38.", "kind": "upgrade", "heroId": "mk7-turbo-hero", "heroCap": "Five groups of connections. Everything else is access.", "variants": {"questions": [{"question": "Which turbo are you fitting?", "hint": "All three bolt to the factory mounting points. Bigger turbos need more supporting hardware.", "options": [{"id": "is38", "label": "Factory IS38 (Golf R / S3)", "when": "The classic bolt-on. Often bought used."}, {"id": "hybrid", "label": "IS38 hybrid", "when": "Bigger wheels in IS38 housings, e.g. CTS or Turbo Concepts."}, {"id": "dtr", "label": "APR DTR", "when": "APR''s drop-in replacement turbo.", "brand": true}]}]}, "glance": {"why": "The biggest power step you can bolt on without changing the engine: roughly 50 whp more than a maxed IS20.", "timeFirst": "6–8 hr", "timeRepeat": "4 hr", "difficulty": 4, "cost": "$1,200–3,500", "risk": "Oil starvation on first start, and stripped turbo studs.", "note": "Turbo cost only. Assumes Stage 2 hardware (intake, intercooler, downpipe) is already on, plus a turbo-specific tune."}, "should": {"yesIf": ["You already run Stage 2 and want more top end", "Your IS20 needs replacing anyway", {"text": "You want 400+ whp and have the fuel system to support it", "only": ["hybrid", "dtr"]}], "codes": [], "notes": ["Required with every route: a tune written for your turbo, an aftermarket downpipe, intake and intercooler, and an upgraded turbo inlet elbow.", "Manual cars: the stock clutch won''t hold IS38 torque. Plan the clutch at the same time.", {"text": "Hybrid turbos aimed at 400+ whp generally need ethanol blends and fuel-system upgrades. Ask the turbo maker what their numbers were made with.", "only": ["hybrid", "dtr"]}], "confidence": {"level": "medium", "n": 4, "note": "Unitronic, IE and FCP Euro requirement lists; mygolfmk7.com''s fact-check of headline turbo claims."}}, "parts": [{"tier": "oe", "name": "IS38 turbocharger", "note": "Used units often come with their oil and coolant lines: worth having.", "price": "$900–1,500", "only": ["is38"]}, {"tier": "aftermarket", "name": "IS38 hybrid turbocharger", "note": "Pick from the aftermarket list.", "price": "$1,800–2,800", "only": ["hybrid"]}, {"tier": "aftermarket", "name": "APR DTR turbocharger", "price": "$2,500–3,500", "only": ["dtr"]}, {"tier": "oe", "name": "Turbo gasket and seal kit", "note": "Turbo-to-head gasket 06L 253 039 A, 4 nuts WHT 007 210, 4 studs N 912 317 01, and the oil and coolant line O-rings. FCP and ECS sell it as a kit.", "price": "$60–120"}, {"tier": "aftermarket", "name": "Turbo-specific tune", "note": "IS38 or hybrid software from your tuner. Never start the swap without it ready.", "price": "$600–900"}, {"tier": "aftermarket", "name": "Turbo inlet elbow", "note": "Required for the IS38 tunes; the factory plastic part chokes at higher boost.", "price": "$150–300"}, {"tier": "oe", "name": "Coolant, about 1 litre", "note": "VW-spec G13 or whatever your car runs.", "price": "$20"}], "aftermarket": [{"name": "CTS Turbo IS38 hybrid", "note": "BDT lists 408 whp on 93 octane with its calibration.", "only": ["is38", "hybrid"]}, {"name": "Turbo Concepts IS38 hybrid", "note": "BDT lists 465 whp on 93 octane: the top of the hybrid range.", "only": ["is38", "hybrid"]}, {"name": "APR DTR", "note": "Drop-in replacement; BDT lists 430 whp on 93 octane.", "only": ["is38", "hybrid"]}], "tools": [{"name": "Triple-square and hex bit sets", "note": "8 mm triple-square for the oil return; 4, 5 and 6 mm hex.", "price": "$40"}, {"name": "10, 12, 13, 15, 16 mm sockets, T25 and T30", "price": "$30"}, {"name": "O2 sensor socket", "price": "$10"}, {"name": "Penetrating oil", "note": "Soak the downpipe and turbo nuts the night before.", "price": "$10"}, {"name": "Torque wrench", "price": "$60"}, {"name": "Laptop or tuning cable for the flash", "price": "$0"}], "before": ["Soak every exhaust nut and the downpipe clamp in penetrating oil the night before.", "Have the tune file ready and the battery on a charger for the flash.", "Work on a cold engine."], "chapters": [{"id": "what", "title": "What you get"}, {"id": "off", "title": "Old turbo out"}, {"id": "on", "title": "New turbo in"}, {"id": "start", "title": "First start and tune"}], "steps": [{"chapter": "what", "title": "What you get", "blocks": [{"t": "chart", "title": "Peak wheel horsepower, 93 octane", "unit": "whp", "baseline": "Stock IS20", "bars": [{"label": "Stock IS20", "v": 220, "note": "estimate"}, {"label": "IS20 Stage 1", "v": 306, "note": "IE, tune only"}, {"label": "IS20 Stage 2", "v": 327, "note": "IE, full bolt-ons"}, {"label": "IS38 (factory)", "v": 365, "note": "BDT"}, {"label": "IS38 hybrid", "v": 408, "note": "CTS, BDT"}, {"label": "APR DTR", "v": 430, "note": "BDT"}], "source": "Tuner-published dyno peaks: Integrated Engineering via RWC Motorsport; Boost Dynamic Tuning Stage 3 table. Stock figure is mygolfmk7.com''s estimate.", "c": {"level": "medium", "n": 3, "note": "Peak figures published by the tuners themselves (APR, Integrated Engineering, Boost Dynamic Tuning), compiled by RWC Motorsport. Your car will vary with fuel, weather and dyno."}}, {"t": "text", "b": "An independent comparison of averaged Stage 2 dyno charts found about 50 whp between a maxed IS20 and an IS38. The IS38 also moves the powerband up a few hundred rpm: a little more lag, much more top end."}]}, {"chapter": "off", "title": "Clear the top of the engine", "blocks": [{"t": "text", "b": "Remove the engine cover, the coil-pack ground wire nuts (10 mm), the intake and the turbo inlet pipe."}]}, {"chapter": "off", "title": "Disconnect the downpipe", "timeSink": true, "blocks": [{"t": "ill", "id": "mk7-turbo-hero", "cap": "Downpipe, lines, bracket and the head nuts."}, {"t": "text", "b": "Undo the downpipe clamp at the turbo (6 mm hex). Underneath, remove the bracket nuts just after the cat (13 mm). Non-Performance Package cars have a small heat shield over the axle (two 16 mm bolts) in the way of the second bracket."}]}, {"chapter": "off", "title": "Disconnect the lines and bracket", "blocks": [{"t": "text", "b": "Remove the 12 mm nuts holding the turbine housing to the head and the oil return bolt (8 mm triple-square). Under the turbo, remove the bracing bracket: 13 mm to the engine, 6 mm hex to the turbo. Unscrew the O2 sensor from the turbo with the sensor socket."}, {"t": "text", "b": "That leaves two coolant lines and the oil feed. The coolant line over the valve cover is easier to free if you loosen its T30 bracket."}]}, {"chapter": "off", "title": "Lift the turbo out", "blocks": [{"t": "text", "b": "Work the turbo up and out. Plug every open line and port with clean rags or caps."}]}, {"chapter": "on", "title": "Prepare the new turbo", "caution": true, "blocks": [{"t": "text", "b": "Fit new studs, a new gasket and every new O-ring from the kit. Move over anything your new turbo doesn''t come with."}, {"t": "note", "b": "Optional while it''s on the bench: the diverter valve comes off with three 4 mm hex bolts if you''re fitting an aftermarket one."}, {"t": "text", "b": "Pour a little clean engine oil into the turbo''s oil feed port and turn the shaft by hand."}]}, {"chapter": "on", "title": "Fit the turbo and lines", "caution": true, "blocks": [{"t": "text", "b": "Seat the turbo on the new gasket and start every nut by hand. Connect the oil feed, both coolant lines and the oil return with new O-rings, then the lower bracket, the O2 sensor and the downpipe."}, {"t": "warn", "b": "Tighten the head nuts evenly to the figure in your kit''s instructions. Stripped studs in the head are the expensive mistake here."}]}, {"chapter": "on", "title": "Inlet, intake and covers", "blocks": [{"t": "text", "b": "Fit the upgraded inlet elbow and the intake, the coil ground wires and the engine cover. Top up the coolant."}]}, {"chapter": "start", "title": "Flash the tune", "caution": true, "blocks": [{"t": "text", "b": "Flash the turbo-specific tune before the first drive, with a battery charger connected."}]}, {"chapter": "start", "title": "First start", "caution": true, "blocks": [{"t": "text", "b": "Start it and let it idle without touching the throttle while oil reaches the turbo. Check every line for oil or coolant leaks, and bleed the cooling system per your car''s procedure."}, {"t": "text", "b": "Drive gently for the first few miles, then log boost and timing on a full pull and send the logs to your tuner."}]}], "alsoReplace": [{"name": "Diverter valve", "why": "Three bolts on the turbo while it''s on the bench."}, {"name": "Clutch (manual cars)", "why": "The stock clutch slips at IS38 torque; the gearbox doesn''t come out for this job, but plan it."}, {"name": "Spark plugs, one step colder", "why": "Many tuners ask for them at IS38 power. Check your tuner''s list."}], "check": {"tab": "Is it healthy?", "title": "Is it healthy?", "illId": "mk7-turbo-hero", "illCap": "Check every connection for leaks after the first drive.", "rows": [{"see": "Clean logs: boost on target, no timing pulled", "means": "Turbo and tune are happy.", "do": "Drive it; re-log after a week."}, {"see": "Oil weeping at the feed or return", "means": "An O-ring not seated.", "do": "Stop and reseat it with a new O-ring."}, {"see": "Boost under target at the top", "means": "A boost leak, often the inlet elbow or a charge pipe.", "do": "Smoke- or pressure-test the intake tract."}], "c": {"level": "medium", "n": 2, "note": "FCP Euro IS38 DIY and tuner guidance."}}, "aftercare": ["Recheck the turbo nuts and downpipe clamp after a few heat cycles.", "Change the engine oil sooner than usual after the swap."], "disagreements": [{"topic": "Headline gains", "pos": "Some ads claim up to 180 hp over stock with an IS38. mygolfmk7.com''s averaged dyno data found about 50 whp over a Stage 2 IS20.", "call": "Expect about 50 whp over a maxed IS20 on pump fuel. Bigger numbers need ethanol and fuel upgrades."}, {"topic": "New or used IS38", "pos": "Used units are cheap from cars that went big-turbo; new ones come with a warranty.", "call": "Used is fine if the shaft has no play and the lines come with it."}], "sources": ["FCP Euro: How to complete a VW Mk7 GTI turbocharger upgrade (IS38)", "mygolfmk7.com: IS20 & IS38 turbo swap checklist (gasket and O-ring part numbers); IS20 vs IS38 power comparison; ECS IS38+ fact check", "RWC Motorsport EA888 Gen3 build guide (compiled dyno figures)", "Boost Dynamic Tuning: complete guide to Mk7/Mk7.5 GTI tuning (Stage 3 turbo table)", "Unitronic and Integrated Engineering software requirement lists"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('intercooler-mk7', '{"title": "Intercooler & charge pipe upgrade", "category": "Forced induction", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "GTI-specific intercoolers fit the Mk7 Golf; the Golf R uses its own.", "kind": "upgrade", "heroId": "mk7-ic-hero", "heroCap": "Hot side from the turbo, cold side to the throttle.", "variants": {"questions": [{"question": "What are you replacing?", "options": [{"id": "ic", "label": "Intercooler only", "when": "Reuses the factory pipes."}, {"id": "pipes", "label": "Intercooler and charge pipes", "when": "Also replaces the plastic cold-side pipe that cracks under boost."}]}]}, "glance": {"why": "Keeps a tuned car''s air cool on repeated pulls, so it stops pulling timing on a hot day.", "timeFirst": "2.5–3.5 hr", "timeRepeat": "1.5 hr", "difficulty": 3, "cost": "$500–1,300", "risk": "A charge pipe coupler not fully seated: it blows off under boost.", "note": "Front bumper comes off. Low end is an intercooler alone; high end includes pipes."}, "should": {"yesIf": ["You''re tuned to Stage 2 or beyond", "Logs show intake temperatures climbing pull after pull", {"text": "The factory plastic charge pipe has cracked, or you''re raising boost", "only": ["pipes"]}], "codes": [], "notes": ["On a Stage 1 car in mild weather, the gain is small: one test measured about 20 whp at most from an aftermarket intercooler on an IS38 car."], "confidence": {"level": "medium", "n": 3, "note": "mygolfmk7.com street testing of stock and aftermarket intercoolers."}}, "parts": [{"tier": "aftermarket", "name": "Stock-location intercooler", "note": "APR, Wagner, Integrated Engineering, CTS and others. Pick from the list.", "price": "$450–900"}, {"tier": "aftermarket", "name": "Charge pipe kit", "note": "Metal hot- and cold-side pipes with silicone couplers.", "price": "$250–450", "only": ["pipes"]}], "aftermarket": [{"name": "APR intercooler", "note": "Bar-and-plate, 27.8 lb. Coolest in mygolfmk7.com''s street tests."}, {"name": "Wagner Tuning Competition intercooler", "note": "Tube-and-fin, 18.5 lb, slightly larger frontal area than the APR."}, {"name": "Integrated Engineering intercooler", "note": "Tested about 5 °F better than the Wagner in one owner''s hybrid-turbo logs."}], "tools": [{"name": "T25 and T30 Torx", "note": "Bumper and charge pipe fasteners.", "price": "$10"}, {"name": "7 mm and 8 mm sockets", "note": "Hose clamps; sizes vary.", "price": "$5"}, {"name": "13 mm socket and thin wrench", "price": "$10"}, {"name": "Pick set", "price": "$10"}], "before": ["Remove the front bumper cover first. See Front bumper cover removal."], "chapters": [{"id": "what", "title": "What you get"}, {"id": "ic", "title": "Intercooler"}, {"id": "pipes", "title": "Charge pipes"}, {"id": "finish", "title": "Finish"}], "steps": [{"chapter": "what", "title": "What you get", "blocks": [{"t": "chart", "title": "Intake air above ambient at 6,000 rpm, 3rd-gear pull", "unit": "°F", "baseline": "Stock IC", "bars": [{"label": "Stock IC", "v": 30, "note": "IS38 car"}, {"label": "Wagner", "v": 14, "note": "12-pull average"}, {"label": "APR", "v": 10, "note": "about 4 °F cooler than Wagner"}], "source": "mygolfmk7.com street logs on an IS38-equipped Mk7 GTI. Lower is better.", "c": {"level": "single", "n": 1, "note": "One owner''s careful, repeated street testing. The best independent data available, but one car."}}, {"t": "text", "b": "The same testing found the aftermarket intercooler kept temperature rise to less than half of stock, and estimated about 20 whp more at the top of a pull. The real benefit is consistency on the second and third pull."}]}, {"chapter": "ic", "title": "Disconnect the factory intercooler", "blocks": [{"t": "ill", "id": "mk7-ic-hero", "cap": "The intercooler sits low behind the bumper."}, {"t": "text", "b": "With the bumper off, loosen the hose clamps on the inlet and outlet couplers, unbolt the intercooler''s brackets (13 mm) and lower it out."}]}, {"chapter": "ic", "title": "Fit the new intercooler", "blocks": [{"t": "text", "b": "Transfer any brackets and rubber mounts. Fit the new core, check its clearance to the AC condenser and the upper brace, and bolt it in."}, {"t": "note", "b": "Some cores fit with only a millimetre or so to the brace. Check nothing is touching before you go on."}]}, {"chapter": "pipes", "only": ["pipes"], "title": "Replace the charge pipes", "timeSink": true, "blocks": [{"t": "text", "b": "Remove the factory hot-side pipe (rubber elbow at the bottom, T30 bolt to the engine) and the plastic cold-side pipe to the throttle body. Fit the new pipes with their silicone couplers, and route every wiring clip as the old ones were."}, {"t": "warn", "b": "Push each coupler fully onto its bead and put the clamp just behind the bead. That''s what keeps it on under boost."}]}, {"chapter": "finish", "title": "Refit and check", "caution": true, "blocks": [{"t": "text", "b": "Connect the couplers, refit the bumper, and start the car. On the first drive, build boost gently and listen for a hiss or a sudden loss of power: either means a coupler has moved."}]}], "alsoReplace": [{"name": "Charge pipes", "why": "The bumper''s already off, and the factory plastic cold-side pipe is a known failure on tuned cars.", "only": ["ic"]}], "check": {"tab": "Is it sealed?", "title": "Is it sealed?", "illId": "mk7-ic-hero", "illCap": "Every coupler, both ends.", "rows": [{"see": "Boost hits target, intake temps flatten pull to pull", "means": "Sealed and working.", "do": "Done."}, {"see": "Hiss under boost, or boost short of target", "means": "A coupler isn''t fully seated.", "do": "Check each clamp is behind its bead."}, {"see": "Rattle from the front at idle", "means": "The core is touching a brace or the condenser.", "do": "Adjust the mounts until it''s clear."}], "c": {"level": "community", "n": 2, "note": "Owner installs."}}, "aftercare": ["Recheck the hose clamps after a few hundred miles."], "disagreements": [{"topic": "Needed at Stage 1?", "pos": "Some say every tuned car needs one; testing on a Stage 1 car shows modest gains.", "call": "Stage 2 and up, or if you live somewhere hot. At Stage 1 it''s optional."}], "sources": ["mygolfmk7.com: stock Mk7 GTI IC evaluation, Wagner street data, IE intercooler claim analysis, intercooler comparison table", "vwvortex: Wagner intercooler Mk7 GTI install notes (clearance)", "ARM Motorsports: Mk7 Jetta GLI front-mount intercooler install guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('downpipe-mk7', '{"title": "Downpipe upgrade", "category": "Forced induction", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "GTI downpipes generally fit the Mk7 Golf 2.0T; check the brand''s fitment.", "kind": "upgrade", "heroId": "mk7-dp-hero", "heroCap": "Turbo clamp, two brackets, one O2 sensor.", "variants": {"questions": [{"question": "Which kind of downpipe?", "hint": "Check your state''s emissions rules before you choose.", "options": [{"id": "cat", "label": "Catted (high-flow cat)", "when": "Keeps a catalytic converter."}, {"id": "nocat", "label": "Catless", "when": "Off-road and track use only in most places."}]}]}, "glance": {"why": "The factory downpipe is the main restriction on a tuned IS20. It''s the core of Stage 2.", "timeFirst": "2.5–4 hr", "timeRepeat": "1.5 hr", "difficulty": 3, "cost": "$400–1,000", "risk": "Seized turbo clamp. Soak it, then soak it again.", "note": "Needs a Stage 2 tune to be worth it, and to keep the check-engine light off."}, "should": {"yesIf": ["You''re going to a Stage 2 tune", "You''re planning an IS38 or hybrid turbo"], "codes": [], "notes": ["A downpipe without a matching tune gains little and can set catalyst fault codes.", {"text": "Catless downpipes fail emissions inspections and aren''t legal for road use in most of the US.", "only": ["nocat"]}], "confidence": {"level": "medium", "n": 3, "note": "Tuner requirement lists (Unitronic, IE, BDT)."}}, "parts": [{"tier": "aftermarket", "name": "3\" downpipe with high-flow cat", "note": "APR, IE, CTS, Unitronic and others.", "price": "$600–1,000", "only": ["cat"]}, {"tier": "aftermarket", "name": "3\" catless downpipe", "price": "$400–600", "only": ["nocat"]}, {"tier": "oe", "name": "Downpipe gasket and new nuts", "note": "Usually supplied with the pipe.", "price": "$15"}, {"tier": "aftermarket", "name": "Stage 2 tune", "note": "Written for your downpipe type.", "price": "$0–200 upgrade"}], "tools": [{"name": "6 mm hex bit on a long extension", "note": "Turbo clamp.", "price": "$10"}, {"name": "13 mm and 16 mm sockets with swivels", "price": "$15"}, {"name": "O2 sensor socket", "price": "$10"}, {"name": "Penetrating oil and patience", "price": "$10"}, {"name": "Anti-seize", "note": "On the new clamp and O2 sensor threads.", "price": "$8"}], "before": ["Soak the turbo clamp and bracket nuts the night before, and again before you start.", "Cold engine: the downpipe holds heat for hours."], "chapters": [{"id": "what", "title": "What you get"}, {"id": "swap", "title": "Swap it"}], "steps": [{"chapter": "what", "title": "What you get", "blocks": [{"t": "chart", "title": "IS20 peak power before and after Stage 2 hardware", "unit": "whp", "baseline": "Stage 1 (tune only)", "bars": [{"label": "Stage 1 (tune only)", "v": 306, "note": "IE"}, {"label": "Stage 2", "v": 327, "note": "IE: downpipe, intake, intercooler"}, {"label": "Stage 1 (APR)", "v": 299}, {"label": "Stage 2 (APR)", "v": 318}], "source": "Tuner-published 93-octane peaks via RWC Motorsport. Stage 2 gains are for the full hardware set, not the downpipe alone.", "c": {"level": "medium", "n": 3, "note": "Peak figures published by the tuners themselves (APR, Integrated Engineering, Boost Dynamic Tuning), compiled by RWC Motorsport. Your car will vary with fuel, weather and dyno."}}, {"t": "text", "b": "The downpipe is the largest single restriction on a tuned IS20, but tuners publish gains for the Stage 2 package as a whole. On its own, without a Stage 2 tune, it does little."}]}, {"chapter": "swap", "title": "Free the turbo end", "timeSink": true, "blocks": [{"t": "ill", "id": "mk7-dp-hero", "cap": "From the turbo outlet back."}, {"t": "text", "b": "From above, with the intake removed for access, undo the downpipe clamp at the turbo (6 mm hex). Unplug the rear O2 sensor connector."}]}, {"chapter": "swap", "title": "Undo the brackets and the rear joint", "blocks": [{"t": "text", "b": "Underneath, remove the bracket nuts just after the cat (13 mm). Non-Performance Package cars: remove the small axle heat shield (two 16 mm bolts) to reach the second one. Separate the downpipe from the cat-back."}]}, {"chapter": "swap", "title": "Drop the old pipe out", "blocks": [{"t": "text", "b": "Work the downpipe down and out past the subframe. Move the O2 sensor to the new pipe with anti-seize on the threads (not the tip)."}]}, {"chapter": "swap", "title": "Fit the new downpipe", "caution": true, "blocks": [{"t": "text", "b": "Hang it loosely at all three points first: turbo clamp, brackets, rear joint. Then tighten from the turbo backwards so nothing is preloaded. Plug in the O2 sensor and route its wire away from the pipe."}]}, {"chapter": "swap", "title": "Flash and check", "blocks": [{"t": "text", "b": "Flash the Stage 2 tune for your downpipe type. Start it and check for exhaust leaks at the turbo clamp with the engine cold, before the gasket seats."}]}], "alsoReplace": [{"name": "Intercooler and intake", "why": "The rest of Stage 2. Tuners write their Stage 2 numbers with all three."}], "check": {"tab": "Sealed?", "title": "Is it sealed?", "illId": "mk7-dp-hero", "illCap": "Three joints and a sensor.", "rows": [{"see": "Quiet at idle, no ticking at the turbo", "means": "The clamp is sealed.", "do": "Recheck it after a few heat cycles."}, {"see": "Ticking that fades as it warms", "means": "A small leak at the turbo clamp.", "do": "Tighten the clamp evenly once it''s cool."}, {"see": "Check-engine light for the catalyst", "means": "The tune doesn''t match the downpipe type.", "do": "Flash the right Stage 2 file."}], "c": {"level": "community", "n": 2, "note": "Owner installs and tuner notes."}}, "aftercare": ["Retighten the turbo clamp and bracket nuts after the first few heat cycles."], "disagreements": [{"topic": "Downpipe-only gains", "pos": "Some quote big gains for the downpipe alone; tuners publish numbers for full Stage 2.", "call": "Count on the Stage 2 package as a whole, not the pipe alone."}], "sources": ["FCP Euro: Mk7 GTI IS38 turbo DIY (downpipe removal steps)", "RWC Motorsport EA888 Gen3 build guide (Stage 1 and 2 figures)", "Unitronic and IE Stage 2 hardware requirements"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('ecu-tune-mk7', '{"title": "ECU tune (Stage 1 & 2)", "category": "Engine", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Same IS20 software family for the Mk7 Golf 2.0T, GLI and 8V A3. Golf R and S3 run IS38 files.", "kind": "upgrade", "heroId": "mk7-tune-hero", "heroCap": "Most Mk7 tunes flash at home through the OBD port.", "variants": {"questions": [{"question": "Which stage?", "options": [{"id": "stage1", "label": "Stage 1", "when": "Software only, stock hardware."}, {"id": "stage2", "label": "Stage 2", "when": "With an intake, intercooler and downpipe fitted."}]}]}, "glance": {"why": "The biggest gain per dollar on the car: around 80 whp from software alone.", "timeFirst": "30–60 min", "timeRepeat": "15 min", "difficulty": 1, "cost": "$500–900", "risk": "A flash interrupted by a flat battery.", "note": "Price is the software plus the tuner''s flashing cable."}, "should": {"yesIf": ["You want much more mid-range and you''re happy with a modified car", {"text": "You''ve fitted (or are fitting) Stage 2 hardware", "only": ["stage2"]}], "codes": [], "notes": ["Manual cars: the stock clutch is near its limit with a tune, especially Stage 2.", "DSG cars: a matching DSG tune is optional at Stage 1 and strongly recommended at Stage 2.", "Tunes are usually written for a specific fuel (91, 93, or ethanol blends). Run the fuel the file was written for."], "confidence": {"level": "medium", "n": 3, "note": "IE, Unitronic and APR product notes; FCP Euro clutch guidance."}}, "parts": [{"tier": "aftermarket", "name": "ECU software", "note": "APR, Integrated Engineering, Unitronic or EQT/COBB. Many include every stage.", "price": "$500–700"}, {"tier": "aftermarket", "name": "Tuner''s flashing cable", "note": "IE POWERlink, APR Ultralink, Unitronic UniCONNECT+ and so on.", "price": "$0–200"}], "aftermarket": [{"name": "Integrated Engineering", "note": "Published 306 whp at Stage 1 on 93 octane."}, {"name": "APR", "note": "Published 299 whp at Stage 1 on 93 octane."}, {"name": "Unitronic", "note": "Published 305 whp at Stage 1; Stage 2+ IS38 files for the turbo route."}, {"name": "EQT (COBB)", "note": "Published 310 whp at Stage 1 with an aggressive calibration."}], "tools": [{"name": "Battery charger or maintainer", "note": "Keeps voltage steady during the flash.", "price": "$40"}, {"name": "Phone or laptop", "price": "$0"}], "before": ["Fill the tank with the fuel the file is written for.", "Connect a battery charger and turn off lights, fan and radio."], "chapters": [{"id": "what", "title": "What you get"}, {"id": "flash", "title": "Flash it"}], "steps": [{"chapter": "what", "title": "What you get", "blocks": [{"t": "chart", "title": "Peak wheel horsepower on 93 octane", "unit": "whp", "baseline": "Stock", "bars": [{"label": "Stock", "v": 220, "note": "estimate"}, {"label": "APR Stage 1", "v": 299}, {"label": "Unitronic Stage 1", "v": 305}, {"label": "IE Stage 1", "v": 306}, {"label": "EQT Stage 1", "v": 310}, {"label": "IE Stage 2", "v": 327, "note": "full bolt-ons"}], "source": "Tuner-published dyno peaks compiled by RWC Motorsport. Different dynos read differently, so compare within a tuner, not across.", "c": {"level": "medium", "n": 4, "note": "Tuner-published 93-octane peaks on stock hardware, compiled by RWC Motorsport; stock figure is mygolfmk7.com''s estimate."}}, {"t": "text", "b": "The biggest change you feel is mid-range torque: the car pulls much harder from low revs in every gear."}]}, {"chapter": "flash", "title": "Connect and back up", "caution": true, "blocks": [{"t": "ill", "id": "mk7-tune-hero", "cap": "App, cable, OBD port."}, {"t": "text", "b": "Plug the tuning cable into the OBD port under the dash, ignition on and engine off. Open the tuner''s app; it identifies the ECU and saves your stock file first. Keep that file somewhere safe."}]}, {"chapter": "flash", "title": "Flash the file", "caution": true, "blocks": [{"t": "text", "b": "Choose the stage and fuel that match your car and start the flash. Don''t open doors, touch switches or unplug anything until the app says it''s done."}, {"t": "text", "b": "Pick the Stage 2 file for your exact hardware, including catted or catless downpipe.", "only": ["stage2"]}]}, {"chapter": "flash", "title": "Clear codes and drive", "blocks": [{"t": "text", "b": "Cycle the ignition, clear any fault codes through the app, and start the car. Drive gently for a few miles, then log a full-throttle pull in third if your tuner supports logging."}]}], "alsoReplace": [{"name": "Spark plugs", "why": "Tuned engines are harder on plugs; many tuners shorten the change interval."}, {"name": "DSG software", "why": "Raises clamping force and shift points to match the new torque.", "only": ["stage2"]}], "check": {"tab": "Running right?", "title": "Is it running right?", "illId": "mk7-tune-hero", "illCap": "Logs tell you more than the butt dyno.", "rows": [{"see": "Smooth pull, boost on target, little timing pulled", "means": "Healthy.", "do": "Enjoy it."}, {"see": "Repeated timing pulls on every cylinder", "means": "Fuel below the file''s octane, or heat.", "do": "Check your fuel; send logs to the tuner."}, {"see": "Clutch flares in high gears", "means": "The clutch is slipping.", "do": "Back off and plan a clutch upgrade."}], "c": {"level": "medium", "n": 2, "note": "Tuner guidance."}}, "aftercare": ["Keep the stock file. Flash back to it before dealer visits if you choose to."], "disagreements": [{"topic": "Which tuner", "pos": "Owners argue endlessly about brands; published numbers are within a few percent.", "call": "Pick on support, logging tools and the upgrade path you want, not the dyno sheet."}], "sources": ["RWC Motorsport EA888 Gen3 build guide (compiled Stage 1 and 2 figures)", "Integrated Engineering, Unitronic and APR software product pages", "mygolfmk7.com (stock power estimate)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('catch-can-mk7', '{"title": "Oil catch can install", "category": "Engine", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Kits for the Mk7 GTI also fit the Mk7 Golf 1.8T and some fit the 2019+ GLI. Golf R and S3 need a washer-filler change.", "kind": "upgrade", "heroId": "mk7-cc-hero", "heroCap": "Breather plate, can, and the return to the intake.", "variants": {"questions": [{"question": "Which kit?", "options": [{"id": "cts", "label": "CTS Turbo", "when": "Billet breather and can with a dipstick.", "brand": true}, {"id": "ie", "label": "Integrated Engineering", "when": "Recirculating, mounts on the engine mount bracket.", "brand": true}, {"id": "o34", "label": "034Motorsport", "when": "Complete PCV replacement, large capacity.", "brand": true}, {"id": "other", "label": "Another kit", "when": "ECS and others."}]}]}, "glance": {"why": "Keeps oil mist out of the intake, so less carbon builds on the valves.", "timeFirst": "1–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$300–600", "risk": "Over-tightening screws into the aluminium valve cover.", "note": "This replaces the factory PCV breather on the valve cover."}, "should": {"yesIf": ["You''re tuned or track the car", "You''ve just had the valves cleaned and want to keep them clean", "The factory PCV breather has failed and you''re replacing it anyway"], "codes": [], "notes": ["Catch cans collect water as well as oil. In freezing weather that can freeze; check and empty it often, or remove it for winter.", {"text": "CTS: check your engine mount bolt has a stud for the bracket. If it''s a flat bolt, you need double-ended stud N 910 296 02.", "only": ["cts"]}], "confidence": {"level": "high", "n": 3, "note": "CTS, IE and 034 product notes."}}, "parts": [{"tier": "aftermarket", "name": "CTS Turbo catch can kit", "price": "$560", "only": ["cts"], "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/b-cts-parts/billet-catch-can-kit/ctsccmk7tsi~cts/"}]}, {"tier": "oe", "name": "Double-ended stud", "pn": "N 910 296 02", "note": "Only if your engine mount has a flat bolt.", "price": "$5", "only": ["cts"]}, {"tier": "aftermarket", "name": "IE recirculating catch can kit", "price": "$300–400", "only": ["ie"], "links": [{"store": "Deutsche Auto Parts", "url": "https://www.shopdap.com/integrated-engineering-ie-mk7-recirculating-catch-can-kit-iebacn1.html"}]}, {"tier": "aftermarket", "name": "034Motorsport billet catch can kit", "price": "$540", "only": ["o34"], "links": [{"store": "NGP Racing", "url": "https://store.ngpracing.com/products/034-motorsport-billet-catch-can-kit-vw-mk7-gti-audi-8v-a3"}]}, {"tier": "aftermarket", "name": "Catch can kit", "note": "Make sure it recirculates rather than venting to the air.", "price": "$250–600", "only": ["other"]}], "aftermarket": [{"name": "CTS Turbo", "note": "Billet breather plate, can with dipstick, -10 AN lines."}, {"name": "Integrated Engineering", "note": "Recirculating, baffled; under an hour to fit on average."}, {"name": "034Motorsport", "note": "High-capacity design, also aimed at oil ingestion on track."}, {"name": "ECS Tuning baffled system", "note": "ECS also sells a baffled system for the Gen3 engine."}], "tools": [{"name": "T30 Torx, 10 and 13 mm wrenches", "price": "$15"}, {"name": "4 and 5 mm hex keys", "price": "$10"}, {"name": "Adjustable wrench", "note": "For the AN fittings.", "price": "$10"}, {"name": "Small torque wrench", "note": "The valve cover is aluminium.", "price": "$40"}], "before": ["Work on a cool engine.", "Have your kit''s instructions open; screw lengths and positions differ between kits."], "chapters": [{"id": "fit", "title": "Fit it"}], "steps": [{"chapter": "fit", "title": "Clear coils 3 and 4", "blocks": [{"t": "ill", "id": "mk7-cc-hero", "cap": "Separator out, breather plate in, can on its bracket."}, {"t": "text", "b": "Remove the engine cover. Unplug the coil harness, remove the 10 mm nuts and studs for coils 3 and 4, and pull those two coils."}]}, {"chapter": "fit", "title": "Swap the factory breather for the kit''s plate", "caution": true, "blocks": [{"t": "text", "b": "Unbolt the factory oil separator from the valve cover and lift it off with its hoses. Transfer the green gasket to the new breather plate if your kit asks you to, and bolt the plate down."}, {"t": "warn", "b": "Don''t over-tighten anything into the valve cover. It''s aluminium and strips easily."}]}, {"chapter": "fit", "title": "Mount the can and run the hoses", "blocks": [{"t": "text", "b": "Fit the bracket and can where your kit specifies, run the hoses from the breather plate to the can and from the can to the intake return, and tighten the AN fittings. Avoid any sag in the lines where water can sit and freeze."}]}, {"chapter": "fit", "title": "Refit coils and check", "blocks": [{"t": "text", "b": "Refit coils 3 and 4 and the harness. Start the engine and check for vacuum leaks: a hiss or an idle that hunts."}]}], "alsoReplace": [{"name": "Intake valve cleaning", "why": "A catch can slows new carbon; it doesn''t remove what''s already there."}], "check": {"tab": "What''s in the can?", "title": "What''s in the can?", "illId": "mk7-cc-hero", "illCap": "Empty it at oil changes.", "rows": [{"see": "A little dark oil", "means": "It''s doing its job.", "do": "Empty it at the next oil change."}, {"see": "Milky, watery sludge", "means": "Condensation from short trips or cold weather.", "do": "Empty it more often; in freezing weather, check weekly."}, {"see": "Nothing at all after thousands of miles", "means": "A hose may be routed wrong.", "do": "Check the lines against your kit''s diagram."}], "c": {"level": "medium", "n": 3, "note": "Kit maker notes and owner experience."}}, "aftercare": ["Empty the can every two to three oil changes, more in cold weather."], "disagreements": [{"topic": "Worth it on a stock car?", "pos": "FCP Euro says even stock engines benefit; others say it''s only for tuned cars.", "call": "Most useful on tuned or tracked cars, and right after a valve cleaning."}], "sources": ["CTS Turbo Mk7/8V catch can install instructions and product notes", "Integrated Engineering recirculating catch can kit notes", "034Motorsport billet catch can kit notes", "FCP Euro: why an oil catch can is an awesome addition"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('catback-mk7', '{"title": "Cat-back exhaust install", "category": "Engine", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Mk7 (2015–2017) and Mk7.5 (2018–2021) rear valances differ: kits are specific to each.", "kind": "upgrade", "heroId": "mk7-catback-hero", "heroCap": "One clamp, one brace, one centre hanger, two rear brackets.", "variants": {"questions": [{"question": "Which car?", "hint": "Tip sections are different between the two.", "options": [{"id": "mk7", "label": "Mk7 (2015–2017)", "when": "Pre-facelift."}, {"id": "mk75", "label": "Mk7.5 (2018–2021)", "when": "Facelift."}]}]}, "glance": {"why": "Sound and looks, mostly. No cutting: the factory system unbolts.", "timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$800–2,500", "risk": "Dropping the system on yourself. Have a helper or a second jack.", "note": "Titanium systems are the high end."}, "should": {"yesIf": ["You want a louder or deeper exhaust note", "The factory muffler is rusted or rattling"], "codes": [], "notes": ["Measured power gains from a cat-back alone are small and rarely published with test conditions. Buy it for the sound.", {"text": "Some kits (APR''s original Mk7 system among them) fit 2015–2017 cars only. Check before ordering.", "only": ["mk7"]}], "confidence": {"level": "medium", "n": 4, "note": "AWE, IE, Unitronic and APR installation guides."}}, "parts": [{"tier": "aftermarket", "name": "Cat-back exhaust kit", "note": "Pick from the list. Most connect to the factory downpipe with a reducer and the factory sleeve clamp.", "price": "$800–2,500"}], "aftermarket": [{"name": "AWE Touring or Track Edition", "note": "Touring is quieter, Track is louder. Reuses the factory sleeve clamp."}, {"name": "Integrated Engineering cat-back", "note": "Separate Mk7 and Mk7.5 kits; tip width differs."}, {"name": "Unitronic cat-back", "note": "Three sections with V-band clamps."}, {"name": "APR cat-back", "note": "Fits 2015–2017 only; uses an unused factory hanger point.", "only": ["mk7"]}, {"name": "COBB / VW Racing titanium", "note": "Separate Mk7 and Mk7.5 part numbers."}], "tools": [{"name": "13 mm and 15 mm sockets, extension", "price": "$10"}, {"name": "Exhaust hanger pliers or a pry bar", "price": "$15"}, {"name": "Jack stands and a second jack", "price": "$80"}, {"name": "Penetrating oil", "price": "$10"}], "before": ["Let the exhaust cool completely.", "Soak the sleeve clamp and hanger bolts."], "chapters": [{"id": "off", "title": "Factory system off"}, {"id": "on", "title": "New system on"}], "steps": [{"chapter": "off", "title": "Loosen the front joint and brace", "blocks": [{"t": "ill", "id": "mk7-catback-hero", "cap": "Front clamp, brace, centre hanger, rear brackets."}, {"t": "text", "b": "Loosen the sleeve clamp where the downpipe meets the cat-back (13 mm). Remove the cross brace under the car if it''s in the way (four 13 mm nuts)."}]}, {"chapter": "off", "title": "Drop the factory system", "caution": true, "blocks": [{"t": "text", "b": "Pry the centre hanger out of its rubber. With a helper or jack supporting the muffler, remove the 13 mm bolts holding each rear hanger bracket to the body, and lower the system out."}, {"t": "text", "b": "Pry the rear hanger brackets off the factory muffler; most kits reuse them."}]}, {"chapter": "on", "title": "Assemble loosely", "blocks": [{"t": "text", "b": "Fit the hangers to the new system. Hang it loosely in the rubbers, starting at the front, with every clamp only finger-tight."}, {"t": "note", "b": "Many kits add a rubber to an unused factory hanger point. Fit it if yours does."}]}, {"chapter": "on", "title": "Centre the tips and tighten", "blocks": [{"t": "text", "b": "Slide the system left and right on its rubbers until the tips are centred in the valance cut-outs. Then tighten from the back forward, finishing at the front sleeve clamp. Refit the brace."}, {"t": "text", "b": "Torque the clamps to your kit''s figures. AWE asks for at least 40 lb-ft on its Accu-Seal clamps."}]}, {"chapter": "on", "title": "Leak check", "blocks": [{"t": "text", "b": "Start it and listen at every joint. Recheck the clamps after a few hundred miles."}]}], "alsoReplace": [{"name": "Downpipe", "why": "If one''s in your plans, fit it first: the cat-back aligns to it."}], "check": {"tab": "Sitting right?", "title": "Sitting right?", "illId": "mk7-catback-hero", "illCap": "Hangers hanging straight down.", "rows": [{"see": "Tips centred, rubbers hanging straight", "means": "No preload on the system.", "do": "Done."}, {"see": "Clunk over bumps", "means": "Pipe touching the body or subframe.", "do": "Re-centre and re-tighten."}, {"see": "Ticking at a joint", "means": "A clamp leak.", "do": "Re-seat and tighten that clamp."}], "c": {"level": "medium", "n": 3, "note": "Kit installation guides."}}, "aftercare": ["Recheck the clamps after 200–500 miles."], "disagreements": [{"topic": "Power from a cat-back", "pos": "Marketing claims gains; measured, conditioned data is scarce.", "call": "Treat any gain as a bonus. Choose on sound."}], "sources": ["AWE Touring/Track Edition Mk7 GTI installation instructions", "Integrated Engineering Mk7/Mk7.5 cat-back install guides", "Unitronic Mk7 GTI cat-back installation instructions", "APR Mk7 GTI cat-back (fitment note) and COBB/VW Racing install guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('carbon-clean-mk7', '{"title": "Intake valve carbon cleaning (walnut blasting)", "category": "Engine", "fits": "2015–2021 GTI (Mk7 / Mk7.5, 2.0T)", "alsoFits": "Any direct-injection EA888; the procedure is the same on the Golf R.", "heroId": "mk7-carbon-hero", "heroCap": "Manifold off, valves closed, blast and vacuum.", "glance": {"why": "Direct injection never washes the intake valves, so carbon builds up and chokes them.", "timeFirst": "5–7 hr", "timeRepeat": "4 hr", "difficulty": 3, "cost": "$300–600", "risk": "Media left in a port goes into the engine. Vacuum everything.", "note": "Cost is a blaster, media and gaskets; a shop typically charges well over $1,000."}, "should": {"yesIf": ["You see rough idle, misfires or a loss of power on a high-mileage car", "A borescope through the intake shows heavy deposits", "It''s been 50,000+ miles and you''re removing the manifold anyway"], "codes": ["P0300", "P0301", "P0302", "P0303", "P0304"], "notes": ["Fit a catch can afterwards to slow the buildup."], "confidence": {"level": "medium", "n": 3, "note": "FCP Euro''s Mk7 GTI walnut blasting DIY and owner experience."}}, "parts": [{"tier": "oe", "name": "Intake manifold gasket set", "note": "Always new.", "price": "$30–60"}, {"name": "Walnut media", "note": "Fine-grit, specifically for intake valve blasting.", "price": "$20–30"}], "aftermarket": [{"name": "034Motorsport carbon cleaning tool", "note": "Port adapter with a vacuum connection, used in FCP Euro''s DIY."}], "tools": [{"name": "Walnut blaster and air compressor", "price": "$150–500"}, {"name": "Shop vacuum", "price": "$60"}, {"name": "24 mm socket and breaker bar", "note": "Turns the crank by hand.", "price": "$15"}, {"name": "Spark plug socket, 10 mm socket", "price": "$15"}, {"name": "Long screwdriver", "note": "Feels for TDC through the plug hole.", "price": "$0"}], "before": ["Read your manual''s intake manifold removal sequence before you start; FCP Euro''s DIY covers it step by step.", "Cover the open ports with tape whenever you''re not working on them."], "chapters": [{"id": "prep", "title": "Get to the valves"}, {"id": "blast", "title": "Blast"}, {"id": "back", "title": "Back together"}], "steps": [{"chapter": "prep", "title": "Coils and plugs out", "blocks": [{"t": "text", "b": "Remove the engine cover, the coil-pack ground wire and 10 mm studs, unplug and pull the coils, and remove the spark plugs. With the plugs out the engine turns easily by hand."}]}, {"chapter": "prep", "title": "Remove the intake manifold", "timeSink": true, "blocks": [{"t": "text", "b": "Remove the intake manifold following your manual. Stuff clean rags into every port straight away."}]}, {"chapter": "blast", "title": "Close the valves for one cylinder", "caution": true, "blocks": [{"t": "ill", "id": "mk7-carbon-hero", "cap": "One port at a time with that cylinder''s valves shut."}, {"t": "text", "b": "Turn the crank clockwise with the 24 mm socket. Feel the piston rise with a long screwdriver in that cylinder''s plug hole: at the top of its compression stroke both intake valves are shut. Confirm by looking into the port."}, {"t": "warn", "b": "Only blast a port whose valves are fully closed. Media through an open valve goes into the cylinder."}]}, {"chapter": "blast", "title": "Blast and vacuum", "blocks": [{"t": "text", "b": "Seal the tool to the port, connect the vacuum, and blast in short bursts until the valve backs are clean metal. Vacuum the port completely."}, {"t": "text", "b": "Turn the crank to bring the next cylinder up on compression and repeat for all four."}]}, {"chapter": "back", "title": "Clean up and refit", "caution": true, "blocks": [{"t": "text", "b": "Vacuum every port again and wipe them with a clean rag. Fit new manifold gaskets and the manifold, then the plugs and coils."}, {"t": "text", "b": "Start it; a rough first few seconds is normal. Clear any misfire codes."}]}], "alsoReplace": [{"name": "Spark plugs", "why": "They''re out already."}, {"name": "Catch can", "why": "Slows the next buildup."}], "check": {"tab": "Clean enough?", "title": "Clean enough?", "illId": "mk7-carbon-hero", "illCap": "Bare metal valve backs, empty ports.", "rows": [{"see": "Bare metal on the valve backs", "means": "Done.", "do": "Vacuum and move to the next cylinder."}, {"see": "Hard carbon left at the edges", "means": "Needs a few more bursts.", "do": "Blast again in short bursts."}, {"see": "Media visible in the port after vacuuming", "means": "Not finished.", "do": "Vacuum again before turning the engine."}], "c": {"level": "medium", "n": 1, "note": "FCP Euro''s Mk7 GTI DIY."}}, "aftercare": ["Recheck for misfire codes after the first drive.", "Plan to check again around every 50,000 miles."], "disagreements": [{"topic": "Interval", "pos": "Some do it every 40,000–60,000 miles; others only when symptoms appear.", "call": "Inspect with a borescope around 50,000 miles and decide from what you see."}], "sources": ["FCP Euro: walnut blasting the intake manifold and valves on a 2016 Mk7 GTI", "bobistheoilguy.com and mbworld.org threads on DI walnut blasting cost and process"], "embeds": []}'::jsonb);
